window.TXB=window.TXB||{};TXB["svd/Act"]={"4:17":"ولكن لئلا تشيع أكثر في الشعب لنهددهما تهديدا أن لا يكلما أحدا من الناس فيما بعد بهذا الاسم».","4:18":"فدعوهما وأوصوهما أن لا ينطقا البتة ولا يعلما باسم يسوع.","4:19":"فأجابهم بطرس ويوحنا: «إن كان حقا أمام الله أن نسمع لكم أكثر من الله فاحكموا.","4:20":"لأننا نحن لا يمكننا أن لا نتكلم بما رأينا وسمعنا».","4:21":"وبعدما هددوهما أيضا أطلقوهما إذ لم يجدوا البتة كيف يعاقبونهما بسبب الشعب لأن الجميع كانوا يمجدون الله على ما جرى","4:22":"لأن الإنسان الذي صارت فيه آية الشفاء هذه كان له أكثر من أربعين سنة.","4:23":"ولما أطلقا أتيا إلى رفقائهما وأخبراهم بكل ما قاله لهما رؤساء الكهنة والشيوخ.","4:24":"فلما سمعوا رفعوا بنفس واحدة صوتا إلى الله وقالوا: «أيها السيد أنت هو الإله الصانع السماء والأرض والبحر وكل ما فيها","4:25":"القائل بفم داود فتاك: لماذا ارتجت الأمم وتفكر الشعوب بالباطل؟","4:26":"قامت ملوك الأرض واجتمع الرؤساء معا على الرب وعلى مسيحه.","4:27":"لأنه بالحقيقة اجتمع على فتاك القدوس يسوع الذي مسحته هيرودس وبيلاطس البنطي مع أمم وشعوب إسرائيل","4:28":"ليفعلوا كل ما سبقت فعينت يدك ومشورتك أن يكون.","4:29":"والآن يا رب انظر إلى تهديداتهم وامنح عبيدك أن يتكلموا بكلامك بكل مجاهرة","4:30":"بمد يدك للشفاء ولتجر آيات وعجائب باسم فتاك القدوس يسوع».","4:31":"ولما صلوا تزعزع المكان الذي كانوا مجتمعين فيه وامتلأ الجميع من الروح القدس وكانوا يتكلمون بكلام الله بمجاهرة.","4:32":"وكان لجمهور الذين آمنوا قلب واحد ونفس واحدة ولم يكن أحد يقول إن شيئا من أمواله له بل كان عندهم كل شيء مشتركا.","4:33":"وبقوة عظيمة كان الرسل يؤدون الشهادة بقيامة الرب يسوع ونعمة عظيمة كانت على جميعهم","4:34":"إذ لم يكن فيهم أحد محتاجا لأن كل الذين كانوا أصحاب حقول أو بيوت كانوا يبيعونها ويأتون بأثمان المبيعات","4:35":"ويضعونها عند أرجل الرسل فكان يوزع على كل أحد كما يكون له احتياج.","4:36":"ويوسف الذي دعي من الرسل برنابا الذي يترجم ابن الوعظ وهو لاوي قبرسي الجنس","4:37":"إذ كان له حقل باعه وأتى بالدراهم ووضعها عند أرجل الرسل.","5:1":"ورجل اسمه حنانيا وامرأته سفيرة باع ملكا","5:2":"واختلس من الثمن وامرأته لها خبر ذلك وأتى بجزء ووضعه عند أرجل الرسل.","5:3":"فقال بطرس: «يا حنانيا لماذا ملأ الشيطان قلبك لتكذب على الروح القدس وتختلس من ثمن الحقل؟","5:4":"أليس وهو باق كان يبقى لك؟ ولما بيع ألم يكن في سلطانك؟ فما بالك وضعت في قلبك هذا الأمر؟ أنت لم تكذب على الناس بل على الله».","5:5":"فلما سمع حنانيا هذا الكلام وقع ومات. وصار خوف عظيم على جميع الذين سمعوا بذلك.","5:6":"فنهض الأحداث ولفوه وحملوه خارجا ودفنوه.","5:7":"ثم حدث بعد مدة نحو ثلاث ساعات أن امرأته دخلت وليس لها خبر ما جرى.","5:8":"فسألها بطرس: «قولي لي أبهذا المقدار بعتما الحقل؟» فقالت: «نعم بهذا المقدار».","5:9":"فقال لها بطرس: «ما بالكما اتفقتما على تجربة روح الرب؟ هوذا أرجل الذين دفنوا رجلك على الباب وسيحملونك خارجا».","5:10":"فوقعت في الحال عند رجليه وماتت. فدخل الشباب ووجدوها ميتة فحملوها خارجا ودفنوها بجانب رجلها.","5:11":"فصار خوف عظيم على جميع الكنيسة وعلى جميع الذين سمعوا بذلك.","5:12":"وجرت على أيدي الرسل آيات وعجائب كثيرة في الشعب. وكان الجميع بنفس واحدة في رواق سليمان.","5:13":"وأما الآخرون فلم يكن أحد منهم يجسر أن يلتصق بهم لكن كان الشعب يعظمهم.","5:14":"وكان مؤمنون ينضمون للرب أكثر جماهير من رجال ونساء","5:15":"حتى إنهم كانوا يحملون المرضى خارجا في الشوارع ويضعونهم على فرش وأسرة حتى إذا جاء بطرس يخيم ولو ظله على أحد منهم.","5:16":"واجتمع جمهور المدن المحيطة إلى أورشليم حاملين مرضى ومعذبين من أرواح نجسة وكانوا يبرأون جميعهم.","5:17":"فقام رئيس الكهنة وجميع الذين معه الذين هم شيعة الصدوقيين وامتلأوا غيرة","5:18":"فألقوا أيديهم على الرسل ووضعوهم في حبس العامة.","5:19":"ولكن ملاك الرب في الليل فتح أبواب السجن وأخرجهم وقال:","5:20":"«اذهبوا قفوا وكلموا الشعب في الهيكل بجميع كلام هذه الحياة».","5:21":"فلما سمعوا دخلوا الهيكل نحو الصبح وجعلوا يعلمون. ثم جاء رئيس الكهنة والذين معه ودعوا المجمع وكل مشيخة بني إسرائيل فأرسلوا إلى الحبس ليؤتى بهم.","5:22":"ولكن الخدام لما جاءوا لم يجدوهم في السجن فرجعوا وأخبروا","5:23":"قائلين: «إننا وجدنا الحبس مغلقا بكل حرص والحراس واقفين خارجا أمام الأبواب ولكن لما فتحنا لم نجد في الداخل أحدا».","5:24":"فلما سمع الكاهن وقائد جند الهيكل ورؤساء الكهنة هذه الأقوال ارتابوا من جهتهم: ما عسى أن يصير هذا؟","5:25":"ثم جاء واحد وأخبرهم قائلا: «هوذا الرجال الذين وضعتموهم في السجن هم في الهيكل واقفين يعلمون الشعب».","5:26":"حينئذ مضى قائد الجند مع الخدام فأحضرهم لا بعنف لأنهم كانوا يخافون الشعب لئلا يرجموا.","5:27":"فلما أحضروهم أوقفوهم في المجمع. فسألهم رئيس الكهنة:","5:28":"«أما أوصيناكم وصية أن لا تعلموا بهذا الاسم؟ وها أنتم قد ملأتم أورشليم بتعليمكم وتريدون أن تجلبوا علينا دم هذا الإنسان».","5:29":"فأجاب بطرس والرسل: «ينبغي أن يطاع الله أكثر من الناس.","5:30":"إله آبائنا أقام يسوع الذي أنتم قتلتموه معلقين إياه على خشبة.","5:31":"هذا رفعه الله بيمينه رئيسا ومخلصا ليعطي إسرائيل التوبة وغفران الخطايا.","5:32":"ونحن شهود له بهذه الأمور والروح القدس أيضا الذي أعطاه الله للذين يطيعونه».","5:33":"فلما سمعوا حنقوا وجعلوا يتشاورون أن يقتلوهم.","5:34":"فقام في المجمع رجل فريسي اسمه غمالائيل معلم للناموس مكرم عند جميع الشعب وأمر أن يخرج الرسل قليلا.","5:35":"ثم قال لهم: « أيها الرجال الإسرائيليون احترزوا لأنفسكم من جهة هؤلاء الناس في ما أنتم مزمعون أن تفعلوا.","5:36":"لأنه قبل هذه الأيام قام ثوداس قائلا عن نفسه إنه شيء الذي التصق به عدد من الرجال نحو أربعمئة الذي قتل وجميع الذين انقادوا إليه تبددوا وصاروا لا شيء.","5:37":"بعد هذا قام يهوذا الجليلي في أيام الاكتتاب وأزاغ وراءه شعبا غفيرا. فذاك أيضا هلك وجميع الذين انقادوا إليه تشتتوا.","5:38":"والآن أقول لكم: تنحوا عن هؤلاء الناس واتركوهم! لأنه إن كان هذا الرأي أو هذا العمل من الناس فسوف ينتقض","5:39":"وإن كان من الله فلا تقدرون أن تنقضوه لئلا توجدوا محاربين لله أيضا».","5:40":"فانقادوا إليه. ودعوا الرسل وجلدوهم وأوصوهم أن لا يتكلموا باسم يسوع ثم أطلقوهم.","5:41":"وأما هم فذهبوا فرحين من أمام المجمع لأنهم حسبوا مستأهلين أن يهانوا من أجل اسمه.","5:42":"وكانوا لا يزالون كل يوم في الهيكل وفي البيوت معلمين ومبشرين بيسوع المسيح.","6:1":"وفي تلك الأيام إذ تكاثر التلاميذ حدث تذمر من اليونانيين على العبرانيين أن أراملهم كن يغفل عنهن في الخدمة اليومية.","6:2":"فدعا الاثنا عشر جمهور التلاميذ وقالوا: «لا يرضي أن نترك نحن كلمة الله ونخدم موائد.","6:3":"فانتخبوا أيها الإخوة سبعة رجال منكم مشهودا لهم ومملوين من الروح القدس وحكمة فنقيمهم على هذه الحاجة.","6:4":"وأما نحن فنواظب على الصلاة وخدمة الكلمة».","6:5":"فحسن هذا القول أمام كل الجمهور فاختاروا استفانوس رجلا مملوا من الإيمان والروح القدس وفيلبس وبروخورس ونيكانور وتيمون وبرميناس ونيقولاوس دخيلا أنطاكيا.","6:6":"الذين أقاموهم أمام الرسل فصلوا ووضعوا عليهم الأيادي.","6:7":"وكانت كلمة الله تنمو وعدد التلاميذ يتكاثر جدا في أورشليم وجمهور كثير من الكهنة يطيعون الإيمان.","9:33":"فوجد هناك إنسانا اسمه إينياس مضطجعا على سرير منذ ثماني سنين وكان مفلوجا.","9:34":"فقال له بطرس: «يا إينياس يشفيك يسوع المسيح. قم وافرش لنفسك». فقام للوقت.","9:35":"ورآه جميع الساكنين في لدة وسارون الذين رجعوا إلى الرب.","9:36":"وكان في يافا تلميذة اسمها طابيثا الذي ترجمته غزالة. هذه كانت ممتلئة أعمالا صالحة وإحسانات كانت تعملها.","9:37":"وحدث في تلك الأيام أنها مرضت وماتت فغسلوها ووضعوها في علية.","9:38":"وإذ كانت لدة قريبة من يافا وسمع التلاميذ أن بطرس فيها أرسلوا رجلين يطلبان إليه أن لا يتوانى عن أن يجتاز إليهم.","9:39":"فقام بطرس وجاء معهما. فلما وصل صعدوا به إلى العلية فوقفت لديه جميع الأرامل يبكين ويرين أقمصة وثيابا مما كانت تعمل غزالة وهي معهن.","9:40":"فأخرج بطرس الجميع خارجا وجثا على ركبتيه وصلى ثم التفت إلى الجسد وقال: «يا طابيثا قومي!» ففتحت عينيها. ولما أبصرت بطرس جلست","9:41":"فناولها يده وأقامها. ثم نادى القديسين والأرامل وأحضرها حية.","9:42":"فصار ذلك معلوما في يافا كلها فآمن كثيرون بالرب.","9:43":"ومكث أياما كثيرة في يافا عند سمعان رجل دباغ.","10:1":"وكان في قيصرية رجل اسمه كرنيليوس قائد مئة من الكتيبة التي تدعى الإيطالية.","10:2":"وهو تقي وخائف الله مع جميع بيته يصنع حسنات كثيرة للشعب ويصلي إلى الله في كل حين.","10:3":"فرأى ظاهرا في رؤيا نحو الساعة التاسعة من النهار ملاكا من الله داخلا إليه وقائلا له: «يا كرنيليوس».","10:4":"فلما شخص إليه ودخله الخوف قال: «ماذا يا سيد؟» فقال له: «صلواتك وصدقاتك صعدت تذكارا أمام الله.","10:5":"والآن أرسل إلى يافا رجالا واستدع سمعان الملقب بطرس.","10:6":"إنه نازل عند سمعان رجل دباغ بيته عند البحر. هو يقول لك ماذا ينبغي أن تفعل».","10:7":"فلما انطلق الملاك الذي كان يكلم كرنيليوس نادى اثنين من خدامه وعسكريا تقيا من الذين كانوا يلازمونه","10:8":"وأخبرهم بكل شيء وأرسلهم إلى يافا.","10:9":"ثم في الغد فيما هم يسافرون ويقتربون إلى المدينة صعد بطرس على السطح ليصلي نحو الساعة السادسة.","10:10":"فجاع كثيرا واشتهى أن يأكل. وبينما هم يهيئون له وقعت عليه غيبة","10:11":"فرأى السماء مفتوحة وإناء نازلا عليه مثل ملاءة عظيمة مربوطة بأربعة أطراف ومدلاة على الأرض.","10:12":"وكان فيها كل دواب الأرض والوحوش والزحافات وطيور السماء.","10:13":"وصار إليه صوت: «قم يا بطرس اذبح وكل».","10:14":"فقال بطرس: «كلا يا رب لأني لم آكل قط شيئا دنسا أو نجسا».","10:15":"فصار إليه أيضا صوت ثانية: «ما طهره الله لا تدنسه أنت!»","10:16":"وكان هذا على ثلاث مرات ثم ارتفع الإناء أيضا إلى السماء.","10:17":"وإذ كان بطرس يرتاب في نفسه: ماذا عسى أن تكون الرؤيا التي رآها؟ إذا الرجال الذين أرسلهم كرنيليوس كانوا قد سألوا عن بيت سمعان ووقفوا على الباب","10:18":"ونادوا يستخبرون: هل سمعان الملقب بطرس نازل هناك؟","10:19":"وبينما بطرس متفكر في الرؤيا قال له الروح: «هوذا ثلاثة رجال يطلبونك.","10:20":"لكن قم وانزل واذهب معهم غير مرتاب في شيء لأني أنا قد أرسلتهم».","10:21":"فنزل بطرس إلى الرجال الذين أرسلهم إليه كرنيليوس وقال: «ها أنا الذي تطلبونه. ما هو السبب الذي حضرتم لأجله؟»","10:22":"فقالوا: «إن كرنيليوس قائد مئة رجلا بارا وخائف الله ومشهودا له من كل أمة اليهود أوحي إليه بملاك مقدس أن يستدعيك إلى بيته ويسمع منك كلاما».","10:23":"فدعاهم إلى داخل وأضافهم. ثم في الغد خرج بطرس معهم وأناس من الإخوة الذين من يافا رافقوه.","10:24":"وفي الغد دخلوا قيصرية. وأما كرنيليوس فكان ينتظرهم وقد دعا أنسباءه وأصدقاءه الأقربين.","10:25":"ولما دخل بطرس استقبله كرنيليوس وسجد واقعا على قدميه.","10:26":"فأقامه بطرس قائلا: «قم أنا أيضا إنسان».","10:27":"ثم دخل وهو يتكلم معه ووجد كثيرين مجتمعين.","10:28":"فقال لهم: «أنتم تعلمون كيف هو محرم على رجل يهودي أن يلتصق بأحد أجنبي أو يأتي إليه. وأما أنا فقد أراني الله أن لا أقول عن إنسان ما إنه دنس أو نجس.","10:29":"فلذلك جئت من دون مناقضة إذ استدعيتموني. فأستخبركم: لأي سبب استدعيتموني؟».","10:30":"فقال كرنيليوس: «منذ أربعة أيام إلى هذه الساعة كنت صائما. وفي الساعة التاسعة كنت أصلي في بيتي وإذا رجل قد وقف أمامي بلباس لامع","10:31":"وقال: يا كرنيليوس سمعت صلاتك وذكرت صدقاتك أمام الله.","10:32":"فأرسل إلى يافا واستدع سمعان الملقب بطرس. إنه نازل في بيت سمعان رجل دباغ عند البحر. فهو متى جاء يكلمك.","10:33":"فأرسلت إليك حالا. وأنت فعلت حسنا إذ جئت. والآن نحن جميعا حاضرون أمام الله لنسمع جميع ما أمرك به الله».","10:34":"فقال بطرس: «بالحق أنا أجد أن الله لا يقبل الوجوه.","10:35":"بل في كل أمة الذي يتقيه ويصنع البر مقبول عنده.","10:36":"الكلمة التي أرسلها إلى بني إسرائيل يبشر بالسلام بيسوع المسيح. هذا هو رب الكل.","10:37":"أنتم تعلمون الأمر الذي صار في كل اليهودية مبتدئا من الجليل بعد المعمودية التي كرز بها يوحنا.","10:38":"يسوع الذي من الناصرة كيف مسحه الله بالروح القدس والقوة الذي جال يصنع خيرا ويشفي جميع المتسلط عليهم إبليس لأن الله كان معه.","10:39":"ونحن شهود بكل ما فعل في كورة اليهودية وفي أورشليم. الذي أيضا قتلوه معلقين إياه على خشبة.","10:40":"هذا أقامه الله في اليوم الثالث وأعطى أن يصير ظاهرا","10:41":"ليس لجميع الشعب بل لشهود سبق الله فانتخبهم. لنا نحن الذين أكلنا وشربنا معه بعد قيامته من الأموات.","10:42":"وأوصانا أن نكرز للشعب ونشهد بأن هذا هو المعين من الله ديانا للأحياء والأموات.","10:43":"له يشهد جميع الأنبياء أن كل من يؤمن به ينال باسمه غفران الخطايا».","10:44":"فبينما بطرس يتكلم بهذه الأمور حل الروح القدس على جميع الذين كانوا يسمعون الكلمة.","10:45":"فاندهش المؤمنون الذين من أهل الختان كل من جاء مع بطرس لأن موهبة الروح القدس قد انسكبت على الأمم أيضا -","10:46":"لأنهم كانوا يسمعونهم يتكلمون بألسنة ويعظمون الله. حينئذ قال بطرس:","10:47":"«أترى يستطيع أحد أن يمنع الماء حتى لا يعتمد هؤلاء الذين قبلوا الروح القدس كما نحن أيضا؟»","10:48":"وأمر أن يعتمدوا باسم الرب. حينئذ سألوه أن يمكث أياما.","11:1":"فسمع الرسل والإخوة الذين كانوا في اليهودية أن الأمم أيضا قبلوا كلمة الله.","11:2":"ولما صعد بطرس إلى أورشليم خاصمه الذين من أهل الختان","11:3":"قائلين: «إنك دخلت إلى رجال ذوي غلفة وأكلت معهم».","11:4":"فابتدأ بطرس يشرح لهم بالتتابع قائلا:","11:5":"«أنا كنت في مدينة يافا أصلي فرأيت في غيبة رؤيا: إناء نازلا مثل ملاءة عظيمة مدلاة بأربعة أطراف من السماء فأتى إلي.","11:6":"فتفرست فيه متأملا فرأيت دواب الأرض والوحوش والزحافات وطيور السماء.","11:7":"وسمعت صوتا قائلا لي: قم يا بطرس اذبح وكل.","11:8":"فقلت: كلا يا رب لأنه لم يدخل فمي قط دنس أو نجس.","11:9":"فأجابني صوت ثانية من السماء: ما طهره الله لا تنجسه أنت.","11:10":"وكان هذا على ثلاث مرات ثم انتشل الجميع إلى السماء أيضا.","11:11":"وإذا ثلاثة رجال قد وقفوا للوقت عند البيت الذي كنت فيه مرسلين إلي من قيصرية.","15:17":"لكي يطلب الباقون من الناس الرب وجميع الأمم الذين دعي اسمي عليهم يقول الرب الصانع هذا كله.","15:18":"معلومة عند الرب منذ الأزل جميع أعماله.","15:19":"لذلك أنا أرى أن لا يثقل على الراجعين إلى الله من الأمم","15:20":"بل يرسل إليهم أن يمتنعوا عن نجاسات الأصنام والزنا والمخنوق والدم.","15:21":"لأن موسى منذ أجيال قديمة له في كل مدينة من يكرز به إذ يقرأ في المجامع كل سبت».","15:22":"حينئذ رأى الرسل والمشايخ مع كل الكنيسة أن يختاروا رجلين منهم فيرسلوهما إلى أنطاكية مع بولس وبرنابا: يهوذا الملقب برسابا وسيلا رجلين متقدمين في الإخوة.","15:23":"وكتبوا بأيديهم هكذا: «الرسل والمشايخ والإخوة يهدون سلاما إلى الإخوة الذين من الأمم في أنطاكية وسورية وكيليكية:","15:24":"إذ قد سمعنا أن أناسا خارجين من عندنا أزعجوكم بأقوال مقلبين أنفسكم وقائلين أن تختتنوا وتحفظوا الناموس - الذين نحن لم نأمرهم.","15:25":"رأينا وقد صرنا بنفس واحدة أن نختار رجلين ونرسلهما إليكم مع حبيبينا برنابا وبولس","15:26":"رجلين قد بذلا نفسيهما لأجل اسم ربنا يسوع المسيح -","15:27":"فقد أرسلنا يهوذا وسيلا وهما يخبرانكم بنفس الأمور شفاها.","15:28":"لأنه قد رأى الروح القدس ونحن أن لا نضع عليكم ثقلا أكثر غير هذه الأشياء الواجبة:","15:29":"أن تمتنعوا عما ذبح للأصنام وعن الدم والمخنوق والزنا التي إن حفظتم أنفسكم منها فنعما تفعلون. كونوا معافين».","15:30":"فهؤلاء لما أطلقوا جاءوا إلى أنطاكية وجمعوا الجمهور ودفعوا الرسالة.","15:31":"فلما قرأوها فرحوا لسبب التعزية.","15:32":"ويهوذا وسيلا إذ كانا هما أيضا نبيين وعظا الإخوة بكلام كثير وشدداهم.","15:33":"ثم بعد ما صرفا زمانا أطلقا بسلام من الإخوة إلى الرسل.","15:34":"ولكن سيلا رأى أن يلبث هناك.","15:35":"أما بولس وبرنابا فأقاما في أنطاكية يعلمان ويبشران مع آخرين كثيرين أيضا بكلمة الرب.","15:36":"ثم بعد أيام قال بولس لبرنابا: «لنرجع ونفتقد إخوتنا في كل مدينة نادينا فيها بكلمة الرب كيف هم».","15:37":"فأشار برنابا أن يأخذا معهما أيضا يوحنا الذي يدعى مرقس","15:38":"وأما بولس فكان يستحسن أن الذي فارقهما من بمفيلية ولم يذهب معهما للعمل لا يأخذانه معهما.","15:39":"فحصل بينهما مشاجرة حتى فارق أحدهما الآخر. وبرنابا أخذ مرقس وسافر في البحر إلى قبرس.","15:40":"وأما بولس فاختار سيلا وخرج مستودعا من الإخوة إلى نعمة الله.","15:41":"فاجتاز في سورية وكيليكية يشدد الكنائس.","16:1":"ثم وصل إلى دربة ولسترة وإذا تلميذ كان هناك اسمه تيموثاوس ابن امرأة يهودية مؤمنة ولكن أباه يوناني","16:2":"وكان مشهودا له من الإخوة الذين في لسترة وإيقونية.","16:3":"فأراد بولس أن يخرج هذا معه فأخذه وختنه من أجل اليهود الذين في تلك الأماكن لأن الجميع كانوا يعرفون أباه أنه يوناني.","16:4":"وإذ كانوا يجتازون في المدن كانوا يسلمونهم القضايا التي حكم بها الرسل والمشايخ الذين في أورشليم ليحفظوها.","16:5":"فكانت الكنائس تتشدد في الإيمان وتزداد في العدد كل يوم.","16:6":"وبعد ما اجتازوا في فريجية وكورة غلاطية منعهم الروح القدس أن يتكلموا بالكلمة في أسيا.","16:7":"فلما أتوا إلى ميسيا حاولوا أن يذهبوا إلى بثينية فلم يدعهم الروح.","16:8":"فمروا على ميسيا وانحدروا إلى ترواس.","16:9":"وظهرت لبولس رؤيا في الليل: رجل مكدوني قائم يطلب إليه ويقول: «اعبر إلى مكدونية وأعنا!».","16:10":"فلما رأى الرؤيا للوقت طلبنا أن نخرج إلى مكدونية متحققين أن الرب قد دعانا لنبشرهم.","16:11":"فأقلعنا من ترواس وتوجهنا بالاستقامة إلى ساموثراكي وفي الغد إلى نيابوليس.","16:12":"ومن هناك إلى فيلبي التي هي أول مدينة من مقاطعة مكدونية وهي كولونية. فأقمنا في هذه المدينة أياما.","16:13":"وفي يوم السبت خرجنا إلى خارج المدينة عند نهر حيث جرت العادة أن تكون صلاة فجلسنا وكنا نكلم النساء اللواتي اجتمعن.","16:14":"فكانت تسمع امرأة اسمها ليدية بياعة أرجوان من مدينة ثياتيرا متعبدة لله ففتح الرب قلبها لتصغي إلى ما كان يقوله بولس.","16:15":"فلما اعتمدت هي وأهل بيتها طلبت قائلة: «إن كنتم قد حكمتم أني مؤمنة بالرب فادخلوا بيتي وامكثوا». فألزمتنا.","16:16":"وحدث بينما كنا ذاهبين إلى الصلاة أن جارية بها روح عرافة استقبلتنا. وكانت تكسب مواليها مكسبا كثيرا بعرافتها.","16:17":"هذه اتبعت بولس وإيانا وصرخت قائلة: «هؤلاء الناس هم عبيد الله العلي الذين ينادون لكم بطريق الخلاص».","16:18":"وكانت تفعل هذا أياما كثيرة. فضجر بولس والتفت إلى الروح وقال: «أنا آمرك باسم يسوع المسيح أن تخرج منها». فخرج في تلك الساعة.","16:19":"فلما رأى مواليها أنه قد خرج رجاء مكسبهم أمسكوا بولس وسيلا وجروهما إلى السوق إلى الحكام.","16:20":"وإذ أتوا بهما إلى الولاة قالوا: «هذان الرجلان يبلبلان مدينتنا وهما يهوديان","16:21":"ويناديان بعوائد لا يجوز لنا أن نقبلها ولا نعمل بها إذ نحن رومانيون».","16:22":"فقام الجمع معا عليهما ومزق الولاة ثيابهما وأمروا أن يضربا بالعصي.","16:23":"فوضعوا عليهما ضربات كثيرة وألقوهما في السجن وأوصوا حافظ السجن أن يحرسهما بضبط.","16:24":"وهو إذ أخذ وصية مثل هذه ألقاهما في السجن الداخلي وضبط أرجلهما في المقطرة.","16:25":"ونحو نصف الليل كان بولس وسيلا يصليان ويسبحان الله والمسجونون يسمعونهما.","16:26":"فحدث بغتة زلزلة عظيمة حتى تزعزعت أساسات السجن فانفتحت في الحال الأبواب كلها وانفكت قيود الجميع.","16:27":"ولما استيقظ حافظ السجن ورأى أبواب السجن مفتوحة استل سيفه وكان مزمعا أن يقتل نفسه ظانا أن المسجونين قد هربوا.","16:28":"فنادى بولس بصوت عظيم قائلا: «لا تفعل بنفسك شيئا رديا لأن جميعنا ههنا».","16:29":"فطلب ضوءا واندفع إلى داخل وخر لبولس وسيلا وهو مرتعد","16:30":"ثم أخرجهما وقال: «يا سيدي ماذا ينبغي أن أفعل لكي أخلص؟»","16:31":"فقالا: «آمن بالرب يسوع المسيح فتخلص أنت وأهل بيتك».","16:32":"وكلماه وجميع من في بيته بكلمة الرب.","16:33":"فأخذهما في تلك الساعة من الليل وغسلهما من الجراحات واعتمد في الحال هو والذين له أجمعون.","16:34":"ولما أصعدهما إلى بيته قدم لهما مائدة وتهلل مع جميع بيته إذ كان قد آمن بالله.","16:35":"ولما صار النهار أرسل الولاة الجلادين قائلين: «أطلق ذينك الرجلين».","16:36":"فأخبر حافظ السجن بولس أن الولاة قد أرسلوا أن تطلقا فاخرجا الآن واذهبا بسلام.","16:37":"فقال لهم بولس: «ضربونا جهرا غير مقضي علينا ونحن رجلان رومانيان وألقونا في السجن - أفالآن يطردوننا سرا؟ كلا! بل ليأتوا هم أنفسهم ويخرجونا».","16:38":"فأخبر الجلادون الولاة بهذا الكلام فاختشوا لما سمعوا أنهما رومانيان.","16:39":"فجاءوا وتضرعوا إليهما وأخرجوهما وسألوهما أن يخرجا من المدينة.","16:40":"فخرجا من السجن ودخلا عند ليدية فأبصرا الإخوة وعزياهم ثم خرجا.","17:1":"فاجتازا في أمفيبوليس وأبولونية وأتيا إلى تسالونيكي حيث كان مجمع اليهود.","17:2":"فدخل بولس إليهم حسب عادته وكان يحاجهم ثلاثة سبوت من الكتب","17:3":"موضحا ومبينا أنه كان ينبغي أن المسيح يتألم ويقوم من الأموات وأن هذا هو المسيح يسوع الذي أنا أنادي لكم به.","17:4":"فاقتنع قوم منهم وانحازوا إلى بولس وسيلا ومن اليونانيين المتعبدين جمهور كثير ومن النساء المتقدمات عدد ليس بقليل.","17:5":"فغار اليهود غير المؤمنين واتخذوا رجالا أشرارا من أهل السوق وتجمعوا وسجسوا المدينة وقاموا على بيت ياسون طالبين أن يحضروهما إلى الشعب.","1:1":"الكلام الأول أنشأته يا ثاوفيلس عن جميع ما ابتدأ يسوع يفعله ويعلم به","1:2":"إلى اليوم الذي ارتفع فيه بعد ما أوصى بالروح القدس الرسل الذين اختارهم.","1:3":"الذين أراهم أيضا نفسه حيا ببراهين كثيرة بعد ما تألم وهو يظهر لهم أربعين يوما ويتكلم عن الأمور المختصة بملكوت الله.","1:4":"وفيما هو مجتمع معهم أوصاهم أن لا يبرحوا من أورشليم بل ينتظروا «موعد الآب الذي سمعتموه مني","1:5":"لأن يوحنا عمد بالماء وأما أنتم فستتعمدون بالروح القدس ليس بعد هذه الأيام بكثير».","1:6":"أما هم المجتمعون فسألوه: «يا رب هل في هذا الوقت ترد الملك إلى إسرائيل؟»","1:7":"فقال لهم: «ليس لكم أن تعرفوا الأزمنة والأوقات التي جعلها الآب في سلطانه","1:8":"لكنكم ستنالون قوة متى حل الروح القدس عليكم وتكونون لي شهودا في أورشليم وفي كل اليهودية والسامرة وإلى أقصى الأرض».","1:9":"ولما قال هذا ارتفع وهم ينظرون وأخذته سحابة عن أعينهم.","1:10":"وفيما كانوا يشخصون إلى السماء وهو منطلق إذا رجلان قد وقفا بهم بلباس أبيض","1:11":"وقالا: «أيها الرجال الجليليون ما بالكم واقفين تنظرون إلى السماء؟ إن يسوع هذا الذي ارتفع عنكم إلى السماء سيأتي هكذا كما رأيتموه منطلقا إلى السماء».","1:12":"حينئذ رجعوا إلى أورشليم من الجبل الذي يدعى جبل الزيتون الذي هو بالقرب من أورشليم على سفر سبت.","1:13":"ولما دخلوا صعدوا إلى العلية التي كانوا يقيمون فيها: بطرس ويعقوب ويوحنا وأندراوس وفيلبس وتوما وبرثولماوس ومتى ويعقوب بن حلفى وسمعان الغيور ويهوذا بن يعقوب.","1:14":"هؤلاء كلهم كانوا يواظبون بنفس واحدة على الصلاة والطلبة مع النساء ومريم أم يسوع ومع إخوته.","1:15":"وفي تلك الأيام قام بطرس في وسط التلاميذ وكان عدة أسماء معا نحو مئة وعشرين. فقال:","1:16":"«أيها الرجال الإخوة كان ينبغي أن يتم هذا المكتوب الذي سبق الروح القدس فقاله بفم داود عن يهوذا الذي صار دليلا للذين قبضوا على يسوع","1:17":"إذ كان معدودا بيننا وصار له نصيب في هذه الخدمة.","1:18":"فإن هذا اقتنى حقلا من أجرة الظلم وإذ سقط على وجهه انشق من الوسط فانسكبت أحشاؤه كلها.","1:19":"وصار ذلك معلوما عند جميع سكان أورشليم حتى دعي ذلك الحقل في لغتهم «حقل دما» (أي: حقل دم).","1:20":"لأنه مكتوب في سفر المزامير: لتصر داره خرابا ولا يكن فيها ساكن وليأخذ وظيفته آخر.","1:21":"فينبغي أن الرجال الذين اجتمعوا معنا كل الزمان الذي فيه دخل إلينا الرب يسوع وخرج","1:22":"منذ معمودية يوحنا إلى اليوم الذي ارتفع فيه عنا يصير واحد منهم شاهدا معنا بقيامته».","1:23":"فأقاموا اثنين: يوسف الذي يدعى بارسابا الملقب يوستس ومتياس.","1:24":"وصلوا قائلين: «أيها الرب العارف قلوب الجميع عين أنت من هذين الاثنين أيا اخترته","1:25":"ليأخذ قرعة هذه الخدمة والرسالة التي تعداها يهوذا ليذهب إلى مكانه».","1:26":"ثم ألقوا قرعتهم فوقعت القرعة على متياس فحسب مع الأحد عشر رسولا.","2:1":"ولما حضر يوم الخمسين كان الجميع معا بنفس واحدة","2:2":"وصار بغتة من السماء صوت كما من هبوب ريح عاصفة وملأ كل البيت حيث كانوا جالسين","2:3":"وظهرت لهم ألسنة منقسمة كأنها من نار واستقرت على كل واحد منهم.","2:4":"وامتلأ الجميع من الروح القدس وابتدأوا يتكلمون بألسنة أخرى كما أعطاهم الروح أن ينطقوا.","2:5":"وكان يهود رجال أتقياء من كل أمة تحت السماء ساكنين في أورشليم.","2:6":"فلما صار هذا الصوت اجتمع الجمهور وتحيروا لأن كل واحد كان يسمعهم يتكلمون بلغته.","2:7":"فبهت الجميع وتعجبوا قائلين بعضهم لبعض: «أترى ليس جميع هؤلاء المتكلمين جليليين؟","2:8":"فكيف نسمع نحن كل واحد منا لغته التي ولد فيها:","2:9":"فرتيون وماديون وعيلاميون والساكنون ما بين النهرين واليهودية وكبدوكية وبنتس وأسيا","2:10":"وفريجية وبمفيلية ومصر ونواحي ليبية التي نحو القيروان والرومانيون المستوطنون يهود ودخلاء","2:11":"كريتيون وعرب نسمعهم يتكلمون بألسنتنا بعظائم الله؟».","2:12":"فتحير الجميع وارتابوا قائلين بعضهم لبعض: «ما عسى أن يكون هذا؟».","2:13":"وكان آخرون يستهزئون قائلين: «إنهم قد امتلأوا سلافة».","2:14":"فوقف بطرس مع الأحد عشر ورفع صوته وقال لهم: «أيها الرجال اليهود والساكنون في أورشليم أجمعون ليكن هذا معلوما عندكم وأصغوا إلى كلامي","2:15":"لأن هؤلاء ليسوا سكارى كما أنتم تظنون لأنها الساعة الثالثة من النهار.","2:16":"بل هذا ما قيل بيوئيل النبي.","2:17":"يقول الله: ويكون في الأيام الأخيرة أني أسكب من روحي على كل بشر فيتنبأ بنوكم وبناتكم ويرى شبابكم رؤى ويحلم شيوخكم أحلاما.","2:18":"وعلى عبيدي أيضا وإمائي أسكب من روحي في تلك الأيام فيتنبأون.","2:19":"وأعطي عجائب في السماء من فوق وآيات على الأرض من أسفل: دما ونارا وبخار دخان.","2:20":"تتحول الشمس إلى ظلمة والقمر إلى دم قبل أن يجيء يوم الرب العظيم الشهير.","2:21":"ويكون كل من يدعو باسم الرب يخلص».","2:22":"«أيها الرجال الإسرائيليون اسمعوا هذه الأقوال: يسوع الناصري رجل قد تبرهن لكم من قبل الله بقوات وعجائب وآيات صنعها الله بيده في وسطكم كما أنتم أيضا تعلمون.","2:23":"هذا أخذتموه مسلما بمشورة الله المحتومة وعلمه السابق وبأيدي أثمة صلبتموه وقتلتموه.","2:24":"الذي أقامه الله ناقضا أوجاع الموت إذ لم يكن ممكنا أن يمسك منه.","2:25":"لأن داود يقول فيه: كنت أرى الرب أمامي في كل حين أنه عن يميني لكي لا أتزعزع.","2:26":"لذلك سر قلبي وتهلل لساني. حتى جسدي أيضا سيسكن على رجاء.","2:27":"لأنك لن تترك نفسي في الهاوية ولا تدع قدوسك يرى فسادا.","2:28":"عرفتني سبل الحياة وستملأني سرورا مع وجهك.","2:29":"أيها الرجال الإخوة يسوغ أن يقال لكم جهارا عن رئيس الآباء داود إنه مات ودفن وقبره عندنا حتى هذا اليوم.","2:30":"فإذ كان نبيا وعلم أن الله حلف له بقسم أنه من ثمرة صلبه يقيم المسيح حسب الجسد ليجلس على كرسيه","2:31":"سبق فرأى وتكلم عن قيامة المسيح أنه لم تترك نفسه في الهاوية ولا رأى جسده فسادا.","2:32":"فيسوع هذا أقامه الله ونحن جميعا شهود لذلك.","2:33":"وإذ ارتفع بيمين الله وأخذ موعد الروح القدس من الآب سكب هذا الذي أنتم الآن تبصرونه وتسمعونه.","2:34":"لأن داود لم يصعد إلى السماوات. وهو نفسه يقول: قال الرب لربي اجلس عن يميني","2:35":"حتى أضع أعداءك موطئا لقدميك.","2:36":"فليعلم يقينا جميع بيت إسرائيل أن الله جعل يسوع هذا الذي صلبتموه أنتم ربا ومسيحا».","2:37":"فلما سمعوا نخسوا في قلوبهم وسألوا بطرس وسائر الرسل: «ماذا نصنع أيها الرجال الإخوة؟»","2:38":"فقال لهم بطرس: «توبوا وليعتمد كل واحد منكم على اسم يسوع المسيح لغفران الخطايا فتقبلوا عطية الروح القدس.","2:39":"لأن الموعد هو لكم ولأولادكم ولكل الذين على بعد كل من يدعوه الرب إلهنا».","2:40":"وبأقوال أخر كثيرة كان يشهد لهم ويعظهم قائلا: «اخلصوا من هذا الجيل الملتوي».","2:41":"فقبلوا كلامه بفرح واعتمدوا وانضم في ذلك اليوم نحو ثلاثة آلاف نفس.","2:42":"وكانوا يواظبون على تعليم الرسل والشركة وكسر الخبز والصلوات.","2:43":"وصار خوف في كل نفس. وكانت عجائب وآيات كثيرة تجرى على أيدي الرسل.","2:44":"وجميع الذين آمنوا كانوا معا وكان عندهم كل شيء مشتركا.","2:45":"والأملاك والمقتنيات كانوا يبيعونها ويقسمونها بين الجميع كما يكون لكل واحد احتياج.","2:46":"وكانوا كل يوم يواظبون في الهيكل بنفس واحدة. وإذ هم يكسرون الخبز في البيوت كانوا يتناولون الطعام بابتهاج وبساطة قلب","2:47":"مسبحين الله ولهم نعمة لدى جميع الشعب. وكان الرب كل يوم يضم إلى الكنيسة الذين يخلصون.","3:1":"وصعد بطرس ويوحنا معا إلى الهيكل في ساعة الصلاة التاسعة.","3:2":"وكان رجل أعرج من بطن أمه يحمل كانوا يضعونه كل يوم عند باب الهيكل الذي يقال له «الجميل» ليسأل صدقة من الذين يدخلون الهيكل.","3:3":"فهذا لما رأى بطرس ويوحنا مزمعين أن يدخلا الهيكل سأل ليأخذ صدقة.","3:4":"فتفرس فيه بطرس مع يوحنا وقال: «انظر إلينا!»","3:5":"فلاحظهما منتظرا أن يأخذ منهما شيئا.","3:6":"فقال بطرس: «ليس لي فضة ولا ذهب ولكن الذي لي فإياه أعطيك: باسم يسوع المسيح الناصري قم وامش».","3:7":"وأمسكه بيده اليمنى وأقامه ففي الحال تشددت رجلاه وكعباه","3:8":"فوثب ووقف وصار يمشي ودخل معهما إلى الهيكل وهو يمشي ويطفر ويسبح الله","3:9":"وأبصره جميع الشعب وهو يمشي ويسبح الله.","3:10":"وعرفوه أنه هو الذي كان يجلس لأجل الصدقة على باب الهيكل الجميل فامتلأوا دهشة وحيرة مما حدث له.","3:11":"وبينما كان الرجل الأعرج الذي شفي متمسكا ببطرس ويوحنا تراكض إليهم جميع الشعب إلى الرواق الذي يقال له «رواق سليمان» وهم مندهشون.","3:12":"فلما رأى بطرس ذلك قال للشعب: «أيها الرجال الإسرائيليون ما بالكم تتعجبون من هذا ولماذا تشخصون إلينا كأننا بقوتنا أو تقوانا قد جعلنا هذا يمشي؟","3:13":"إن إله إبراهيم وإسحاق ويعقوب إله آبائنا مجد فتاه يسوع الذي أسلمتموه أنتم وأنكرتموه أمام وجه بيلاطس وهو حاكم بإطلاقه.","3:14":"ولكن أنتم أنكرتم القدوس البار وطلبتم أن يوهب لكم رجل قاتل.","3:15":"ورئيس الحياة قتلتموه الذي أقامه الله من الأموات ونحن شهود لذلك.","3:16":"وبالإيمان باسمه شدد اسمه هذا الذي تنظرونه وتعرفونه والإيمان الذي بواسطته أعطاه هذه الصحة أمام جميعكم.","3:17":"«والآن أيها الإخوة أنا أعلم أنكم بجهالة عملتم كما رؤساؤكم أيضا.","3:18":"وأما الله فما سبق وأنبأ به بأفواه جميع أنبيائه أن يتألم المسيح قد تممه هكذا.","3:19":"فتوبوا وارجعوا لتمحى خطاياكم لكي تأتي أوقات الفرج من وجه الرب.","3:20":"ويرسل يسوع المسيح المبشر به لكم قبل.","3:21":"الذي ينبغي أن السماء تقبله إلى أزمنة رد كل شيء التي تكلم عنها الله بفم جميع أنبيائه القديسين منذ الدهر.","3:22":"فإن موسى قال للآباء: إن نبيا مثلي سيقيم لكم الرب إلهكم من إخوتكم. له تسمعون في كل ما يكلمكم به.","3:23":"ويكون أن كل نفس لا تسمع لذلك النبي تباد من الشعب.","3:24":"وجميع الأنبياء أيضا من صموئيل فما بعده جميع الذين تكلموا سبقوا وأنبأوا بهذه الأيام.","3:25":"أنتم أبناء الأنبياء والعهد الذي عاهد به الله آباءنا قائلا لإبراهيم: وبنسلك تتبارك جميع قبائل الأرض.","3:26":"إليكم أولا إذ أقام الله فتاه يسوع أرسله يبارككم برد كل واحد منكم عن شروره».","4:1":"وبينما هما يخاطبان الشعب أقبل عليهما الكهنة وقائد جند الهيكل والصدوقيون","4:2":"متضجرين من تعليمهما الشعب وندائهما في يسوع بالقيامة من الأموات.","4:3":"فألقوا عليهما الأيادي ووضعوهما في حبس إلى الغد لأنه كان قد صار المساء.","4:4":"وكثيرون من الذين سمعوا الكلمة آمنوا وصار عدد الرجال نحو خمسة آلاف.","4:5":"وحدث في الغد أن رؤساءهم وشيوخهم وكتبتهم اجتمعوا إلى أورشليم","4:6":"مع حنان رئيس الكهنة وقيافا ويوحنا والإسكندر وجميع الذين كانوا من عشيرة رؤساء الكهنة.","4:7":"ولما أقاموهما في الوسط جعلوا يسألونهما: «بأية قوة وبأي اسم صنعتما أنتما هذا؟»","4:8":"حينئذ امتلأ بطرس من الروح القدس وقال لهم: «يا رؤساء الشعب وشيوخ إسرائيل","4:9":"إن كنا نفحص اليوم عن إحسان إلى إنسان سقيم بماذا شفي هذا","4:10":"فليكن معلوما عند جميعكم وجميع شعب إسرائيل أنه باسم يسوع المسيح الناصري الذي صلبتموه أنتم الذي أقامه الله من الأموات بذاك وقف هذا أمامكم صحيحا.","4:11":"هذا هو الحجر الذي احتقرتموه أيها البناؤون الذي صار رأس الزاوية.","4:12":"وليس بأحد غيره الخلاص. لأن ليس اسم آخر تحت السماء قد أعطي بين الناس به ينبغي أن نخلص».","4:13":"فلما رأوا مجاهرة بطرس ويوحنا ووجدوا أنهما إنسانان عديما العلم وعاميان تعجبوا. فعرفوهما أنهما كانا مع يسوع.","4:14":"ولكن إذ نظروا الإنسان الذي شفي واقفا معهما لم يكن لهم شيء يناقضون به.","4:15":"فأمروهما أن يخرجا إلى خارج المجمع وتآمروا فيما بينهم","4:16":"قائلين: «ماذا نفعل بهذين الرجلين؟ لأنه ظاهر لجميع سكان أورشليم أن آية معلومة قد جرت بأيديهما ولا نقدر أن ننكر.","6:8":"وأما استفانوس فإذ كان مملوا إيمانا وقوة كان يصنع عجائب وآيات عظيمة في الشعب.","6:9":"فنهض قوم من المجمع الذي يقال له مجمع الليبرتينيين والقيروانيين والإسكندريين ومن الذين من كيليكيا وأسيا يحاورون استفانوس.","6:10":"ولم يقدروا أن يقاوموا الحكمة والروح الذي كان يتكلم به.","6:11":"حينئذ دسوا لرجال يقولون: «إننا سمعناه يتكلم بكلام تجديف على موسى وعلى الله».","6:12":"وهيجوا الشعب والشيوخ والكتبة فقاموا وخطفوه وأتوا به إلى المجمع","6:13":"وأقاموا شهودا كذبة يقولون: «هذا الرجل لا يفتر عن أن يتكلم تجديفا ضد هذا الموضع المقدس والناموس","6:14":"لأننا سمعناه يقول: إن يسوع الناصري هذا سينقض هذا الموضع ويغير العوائد التي سلمنا إياها موسى».","6:15":"فشخص إليه جميع الجالسين في المجمع ورأوا وجهه كأنه وجه ملاك.","7:1":"فسأل رئيس الكهنة: «أترى هذه الأمور هكذا هي؟»","7:2":"فأجاب: «أيها الرجال الإخوة والآباء اسمعوا. ظهر إله المجد لأبينا إبراهيم وهو في ما بين النهرين قبلما سكن في حاران","7:3":"وقال له: اخرج من أرضك ومن عشيرتك وهلم إلى الأرض التي أريك","7:4":"فخرج حينئذ من أرض الكلدانيين وسكن في حاران. ومن هناك نقله بعد ما مات أبوه إلى هذه الأرض التي أنتم الآن ساكنون فيها.","7:5":"ولم يعطه فيها ميراثا ولا وطأة قدم ولكن وعد أن يعطيها ملكا له ولنسله من بعده ولم يكن له بعد ولد.","7:6":"وتكلم الله هكذا: أن يكون نسله متغربا في أرض غريبة فيستعبدوه ويسيئوا إليه أربع مئة سنة","7:7":"والأمة التي يستعبدون لها سأدينها أنا يقول الله. وبعد ذلك يخرجون ويعبدونني في هذا المكان.","7:8":"وأعطاه عهد الختان وهكذا ولد إسحاق وختنه في اليوم الثامن. وإسحاق ولد يعقوب ويعقوب ولد رؤساء الآباء الاثني عشر.","7:9":"ورؤساء الآباء حسدوا يوسف وباعوه إلى مصر وكان الله معه","7:10":"وأنقذه من جميع ضيقاته وأعطاه نعمة وحكمة أمام فرعون ملك مصر فأقامه مدبرا على مصر وعلى كل بيته.","7:11":"ثم أتى جوع على كل أرض مصر وكنعان وضيق عظيم فكان آباؤنا لا يجدون قوتا.","7:12":"ولما سمع يعقوب أن في مصر قمحا أرسل آباءنا أول مرة.","7:13":"وفي المرة الثانية استعرف يوسف إلى إخوته واستعلنت عشيرة يوسف لفرعون.","7:14":"فأرسل يوسف واستدعى أباه يعقوب وجميع عشيرته خمسة وسبعين نفسا.","7:15":"فنزل يعقوب إلى مصر ومات هو وآباؤنا","7:16":"ونقلوا إلى شكيم ووضعوا في القبر الذي اشتراه إبراهيم بثمن فضة من بني حمور أبي شكيم.","7:17":"وكما كان يقرب وقت الموعد الذي أقسم الله عليه لإبراهيم كان الشعب ينمو ويكثر في مصر","7:18":"إلى أن قام ملك آخر لم يكن يعرف يوسف.","7:19":"فاحتال هذا على جنسنا وأساء إلى آبائنا حتى جعلوا أطفالهم منبوذين لكي لا يعيشوا.","7:20":"«وفي ذلك الوقت ولد موسى وكان جميلا جدا فربي هذا ثلاثة أشهر في بيت أبيه.","7:21":"ولما نبذ اتخذته ابنة فرعون وربته لنفسها ابنا.","7:22":"فتهذب موسى بكل حكمة المصريين وكان مقتدرا في الأقوال والأعمال.","7:23":"ولما كملت له مدة أربعين سنة خطر على باله أن يفتقد إخوته بني إسرائيل.","7:24":"وإذ رأى واحدا مظلوما حامى عنه وأنصف المغلوب إذ قتل المصري.","7:25":"فظن أن إخوته يفهمون أن الله على يده يعطيهم نجاة وأما هم فلم يفهموا.","7:26":"وفي اليوم الثاني ظهر لهم وهم يتخاصمون فساقهم إلى السلامة قائلا: أيها الرجال أنتم إخوة. لماذا تظلمون بعضكم بعضا؟","7:27":"فالذي كان يظلم قريبه دفعه قائلا: من أقامك رئيسا وقاضيا علينا؟","7:28":"أتريد أن تقتلني كما قتلت أمس المصري؟","7:29":"فهرب موسى بسبب هذه الكلمة وصار غريبا في أرض مديان حيث ولد ابنين.","7:30":"«ولما كملت أربعون سنة ظهر له ملاك الرب في برية جبل سيناء في لهيب نار عليقة.","7:31":"فلما رأى موسى ذلك تعجب من المنظر. وفيما هو يتقدم ليتطلع صار إليه صوت الرب:","7:32":"أنا إله آبائك إله إبراهيم وإله إسحاق وإله يعقوب. فارتعد موسى ولم يجسر أن يتطلع.","7:33":"فقال له الرب: اخلع نعل رجليك لأن الموضع الذي أنت واقف عليه أرض مقدسة.","7:34":"إني رأيت مشقة شعبي الذين في مصر وسمعت أنينهم ونزلت لأنقذهم. فهلم الآن أرسلك إلى مصر.","7:35":"«هذا موسى الذي أنكروه قائلين: من أقامك رئيسا وقاضيا؟ هذا أرسله الله رئيسا وفاديا بيد الملاك الذي ظهر له في العليقة.","7:36":"هذا أخرجهم صانعا عجائب وآيات في أرض مصر وفي البحر الأحمر وفي البرية أربعين سنة.","7:37":"«هذا هو موسى الذي قال لبني إسرائيل: نبيا مثلي سيقيم لكم الرب إلهكم من إخوتكم. له تسمعون.","7:38":"هذا هو الذي كان في الكنيسة في البرية مع الملاك الذي كان يكلمه في جبل سيناء ومع آبائنا. الذي قبل أقوالا حية ليعطينا إياها.","7:39":"الذي لم يشأ آباؤنا أن يكونوا طائعين له بل دفعوه ورجعوا بقلوبهم إلى مصر","7:40":"قائلين لهارون: اعمل لنا آلهة تتقدم أمامنا لأن هذا موسى الذي أخرجنا من أرض مصر لا نعلم ماذا أصابه.","7:41":"فعملوا عجلا في تلك الأيام وأصعدوا ذبيحة للصنم وفرحوا بأعمال أيديهم.","7:42":"فرجع الله وأسلمهم ليعبدوا جند السماء كما هو مكتوب في كتاب الأنبياء: هل قربتم لي ذبائح وقرابين أربعين سنة في البرية يا بيت إسرائيل؟","7:43":"بل حملتم خيمة مولوك ونجم إلهكم رمفان التماثيل التي صنعتموها لتسجدوا لها. فأنقلكم إلى ما وراء بابل.","7:44":"«وأما خيمة الشهادة فكانت مع آبائنا في البرية كما أمر الذي كلم موسى أن يعملها على المثال الذي كان قد رآه","7:45":"التي أدخلها أيضا آباؤنا إذ تخلفوا عليها مع يشوع في ملك الأمم الذين طردهم الله من وجه آبائنا إلى أيام داود","7:46":"الذي وجد نعمة أمام الله والتمس أن يجد مسكنا لإله يعقوب.","7:47":"ولكن سليمان بنى له بيتا.","7:48":"لكن العلي لا يسكن في هياكل مصنوعة بالأيادي كما يقول النبي:","7:49":"السماء كرسي لي والأرض موطئ لقدمي. أي بيت تبنون لي يقول الرب وأي هو مكان راحتي؟","7:50":"أليست يدي صنعت هذه الأشياء كلها؟","7:51":"«يا قساة الرقاب وغير المختونين بالقلوب والآذان أنتم دائما تقاومون الروح القدس. كما كان آباؤكم كذلك أنتم.","7:52":"أي الأنبياء لم يضطهده آباؤكم وقد قتلوا الذين سبقوا فأنبأوا بمجيء البار الذي أنتم الآن صرتم مسلميه وقاتليه","7:53":"الذين أخذتم الناموس بترتيب ملائكة ولم تحفظوه؟».","7:54":"فلما سمعوا هذا حنقوا بقلوبهم وصروا بأسنانهم عليه.","7:55":"وأما هو فشخص إلى السماء وهو ممتلئ من الروح القدس فرأى مجد الله ويسوع قائما عن يمين الله.","7:56":"فقال: «ها أنا أنظر السماوات مفتوحة وابن الإنسان قائما عن يمين الله».","7:57":"فصاحوا بصوت عظيم وسدوا آذانهم وهجموا عليه بنفس واحدة","7:58":"وأخرجوه خارج المدينة ورجموه. والشهود خلعوا ثيابهم عند رجلي شاب يقال له شاول.","7:59":"فكانوا يرجمون استفانوس وهو يدعو ويقول: «أيها الرب يسوع اقبل روحي».","7:60":"ثم جثا على ركبتيه وصرخ بصوت عظيم: «يا رب لا تقم لهم هذه الخطية». وإذ قال هذا رقد.","8:1":"وكان شاول راضيا بقتله. وحدث في ذلك اليوم اضطهاد عظيم على الكنيسة التي في أورشليم فتشتت الجميع في كور اليهودية والسامرة ما عدا الرسل.","8:2":"وحمل رجال أتقياء استفانوس وعملوا عليه مناحة عظيمة.","8:3":"وأما شاول فكان يسطو على الكنيسة وهو يدخل البيوت ويجر رجالا ونساء ويسلمهم إلى السجن.","8:4":"فالذين تشتتوا جالوا مبشرين بالكلمة.","8:5":"فانحدر فيلبس إلى مدينة من السامرة وكان يكرز لهم بالمسيح.","8:6":"وكان الجموع يصغون بنفس واحدة إلى ما يقوله فيلبس عند استماعهم ونظرهم الآيات التي صنعها","8:7":"لأن كثيرين من الذين بهم أرواح نجسة كانت تخرج صارخة بصوت عظيم وكثيرون من المفلوجين والعرج شفوا.","8:8":"فكان فرح عظيم في تلك المدينة.","8:9":"وكان قبلا في المدينة رجل اسمه سيمون يستعمل السحر ويدهش شعب السامرة قائلا: «إنه شيء عظيم!».","8:10":"وكان الجميع يتبعونه من الصغير إلى الكبير قائلين: «هذا هو قوة الله العظيمة».","8:11":"وكانوا يتبعونه لكونهم قد اندهشوا زمانا طويلا بسحره.","8:12":"ولكن لما صدقوا فيلبس وهو يبشر بالأمور المختصة بملكوت الله وباسم يسوع المسيح اعتمدوا رجالا ونساء.","8:13":"وسيمون أيضا نفسه آمن. ولما اعتمد كان يلازم فيلبس وإذ رأى آيات وقوات عظيمة تجرى اندهش.","8:14":"ولما سمع الرسل الذين في أورشليم أن السامرة قد قبلت كلمة الله أرسلوا إليهم بطرس ويوحنا","8:15":"اللذين لما نزلا صليا لأجلهم لكي يقبلوا الروح القدس","8:16":"لأنه لم يكن قد حل بعد على أحد منهم - غير أنهم كانوا معتمدين باسم الرب يسوع.","8:17":"حينئذ وضعا الأيادي عليهم فقبلوا الروح القدس.","8:18":"ولما رأى سيمون أنه بوضع أيدي الرسل يعطى الروح القدس قدم لهما دراهم","8:19":"قائلا: «أعطياني أنا أيضا هذا السلطان حتى أي من وضعت عليه يدي يقبل الروح القدس».","8:20":"فقال له بطرس: «لتكن فضتك معك للهلاك لأنك ظننت أن تقتني موهبة الله بدراهم.","8:21":"ليس لك نصيب ولا قرعة في هذا الأمر لأن قلبك ليس مستقيما أمام الله.","8:22":"فتب من شرك هذا واطلب إلى الله عسى أن يغفر لك فكر قلبك","8:23":"لأني أراك في مرارة المر ورباط الظلم».","8:24":"فأجاب سيمون: «اطلبا أنتما إلى الرب من أجلي لكي لا يأتي علي شيء مما ذكرتما».","8:25":"ثم إنهما بعد ما شهدا وتكلما بكلمة الرب رجعا إلى أورشليم وبشرا قرى كثيرة للسامريين.","8:26":"ثم إن ملاك الرب قال لفيلبس: «قم واذهب نحو الجنوب على الطريق المنحدرة من أورشليم إلى غزة» التي هي برية.","8:27":"فقام وذهب. وإذا رجل حبشي خصي وزير لكنداكة ملكة الحبشة كان على جميع خزائنها - فهذا كان قد جاء إلى أورشليم ليسجد.","8:28":"وكان راجعا وجالسا على مركبته وهو يقرأ النبي إشعياء.","8:29":"فقال الروح لفيلبس: «تقدم ورافق هذه المركبة».","8:30":"فبادر إليه فيلبس وسمعه يقرأ النبي إشعياء فسأله: «ألعلك تفهم ما أنت تقرأ؟»","8:31":"فأجاب: «كيف يمكنني إن لم يرشدني أحد؟». وطلب إلى فيلبس أن يصعد ويجلس معه.","8:32":"وأما فصل الكتاب الذي كان يقرأه فكان هذا: «مثل شاة سيق إلى الذبح ومثل خروف صامت أمام الذي يجزه هكذا لم يفتح فاه.","8:33":"في تواضعه انتزع قضاؤه وجيله من يخبر به لأن حياته تنتزع من الأرض؟»","8:34":"فسأل الخصي فيلبس: «أطلب إليك: عن من يقول النبي هذا؟ عن نفسه أم عن واحد آخر؟»","8:35":"فابتدأ فيلبس من هذا الكتاب يبشره بيسوع.","8:36":"وفيما هما سائران في الطريق أقبلا على ماء فقال الخصي: «هوذا ماء. ماذا يمنع أن أعتمد؟»","8:37":"فقال فيلبس: «إن كنت تؤمن من كل قلبك يجوز». فأجاب: «أنا أومن أن يسوع المسيح هو ابن الله».","8:38":"فأمر أن تقف المركبة فنزلا كلاهما إلى الماء فيلبس والخصي فعمده.","8:39":"ولما صعدا من الماء خطف روح الرب فيلبس فلم يبصره الخصي أيضا وذهب في طريقه فرحا.","8:40":"وأما فيلبس فوجد في أشدود. وبينما هو مجتاز كان يبشر جميع المدن حتى جاء إلى قيصرية.","9:1":"أما شاول فكان لم يزل ينفث تهددا وقتلا على تلاميذ الرب فتقدم إلى رئيس الكهنة","9:2":"وطلب منه رسائل إلى دمشق إلى الجماعات حتى إذا وجد أناسا من الطريق رجالا أو نساء يسوقهم موثقين إلى أورشليم.","9:3":"وفي ذهابه حدث أنه اقترب إلى دمشق فبغتة أبرق حوله نور من السماء","9:4":"فسقط على الأرض وسمع صوتا قائلا له: «شاول شاول لماذا تضطهدني؟»","9:5":"فسأله: «من أنت يا سيد؟» فقال الرب: «أنا يسوع الذي أنت تضطهده. صعب عليك أن ترفس مناخس».","9:6":"فسأل وهو مرتعد ومتحير: «يا رب ماذا تريد أن أفعل؟»فقال له الرب: «قم وادخل المدينة فيقال لك ماذا ينبغي أن تفعل».","9:7":"وأما الرجال المسافرون معه فوقفوا صامتين يسمعون الصوت ولا ينظرون أحدا.","9:8":"فنهض شاول عن الأرض وكان وهو مفتوح العينين لا يبصر أحدا. فاقتادوه بيده وأدخلوه إلى دمشق.","9:9":"وكان ثلاثة أيام لا يبصر فلم يأكل ولم يشرب.","9:10":"وكان في دمشق تلميذ اسمه حنانيا فقال له الرب في رؤيا: «يا حنانيا». فقال: «هأنذا يا رب».","9:11":"فقال له الرب: «قم واذهب إلى الزقاق الذي يقال له المستقيم واطلب في بيت يهوذا رجلا طرسوسيا اسمه شاول - لأنه هوذا يصلي.","9:12":"وقد رأى في رؤيا رجلا اسمه حنانيا داخلا وواضعا يده عليه لكي يبصر».","9:13":"فأجاب حنانيا: «يا رب قد سمعت من كثيرين عن هذا الرجل كم من الشرور فعل بقديسيك في أورشليم.","9:14":"وههنا له سلطان من رؤساء الكهنة أن يوثق جميع الذين يدعون باسمك».","9:15":"فقال له الرب: «اذهب لأن هذا لي إناء مختار ليحمل اسمي أمام أمم وملوك وبني إسرائيل.","9:16":"لأني سأريه كم ينبغي أن يتألم من أجل اسمي».","9:17":"فمضى حنانيا ودخل البيت ووضع عليه يديه وقال: «أيها الأخ شاول قد أرسلني الرب يسوع الذي ظهر لك في الطريق الذي جئت فيه لكي تبصر وتمتلئ من الروح القدس».","9:18":"فللوقت وقع من عينيه شيء كأنه قشور فأبصر في الحال وقام واعتمد.","9:19":"وتناول طعاما فتقوى. وكان شاول مع التلاميذ الذين في دمشق أياما.","9:20":"وللوقت جعل يكرز في المجامع بالمسيح «أن هذا هو ابن الله».","9:21":"فبهت جميع الذين كانوا يسمعون وقالوا: «أليس هذا هو الذي أهلك في أورشليم الذين يدعون بهذا الاسم وقد جاء إلى هنا: ليسوقهم موثقين إلى رؤساء الكهنة؟».","9:22":"وأما شاول فكان يزداد قوة ويحير اليهود الساكنين في دمشق محققا «أن هذا هو المسيح».","9:23":"ولما تمت أيام كثيرة تشاور اليهود ليقتلوه","9:24":"فعلم شاول بمكيدتهم. وكانوا يراقبون الأبواب أيضا نهارا وليلا ليقتلوه.","9:25":"فأخذه التلاميذ ليلا وأنزلوه من السور مدلين إياه في سل.","9:26":"ولما جاء شاول إلى أورشليم حاول أن يلتصق بالتلاميذ وكان الجميع يخافونه غير مصدقين أنه تلميذ.","9:27":"فأخذه برنابا وأحضره إلى الرسل وحدثهم كيف أبصر الرب في الطريق وأنه كلمه وكيف جاهر في دمشق باسم يسوع.","9:28":"فكان معهم يدخل ويخرج في أورشليم ويجاهر باسم الرب يسوع.","9:29":"وكان يخاطب ويباحث اليونانيين فحاولوا أن يقتلوه.","9:30":"فلما علم الإخوة أحدروه إلى قيصرية وأرسلوه إلى طرسوس.","9:31":"وأما الكنائس في جميع اليهودية والجليل والسامرة فكان لها سلام وكانت تبنى وتسير في خوف الرب وبتعزية الروح القدس كانت تتكاثر.","9:32":"وحدث أن بطرس وهو يجتاز بالجميع نزل أيضا إلى القديسين الساكنين في لدة","11:12":"فقال لي الروح أن أذهب معهم غير مرتاب في شيء. وذهب معي أيضا هؤلاء الإخوة الستة. فدخلنا بيت الرجل","11:13":"فأخبرنا كيف رأى الملاك في بيته قائما وقائلا له: أرسل إلى يافا رجالا واستدع سمعان الملقب بطرس","11:14":"وهو يكلمك كلاما به تخلص أنت وكل بيتك.","11:15":"فلما ابتدأت أتكلم حل الروح القدس عليهم كما علينا أيضا في البداءة.","11:16":"فتذكرت كلام الرب كيف قال: إن يوحنا عمد بماء وأما أنتم فستعمدون بالروح القدس.","11:17":"فإن كان الله قد أعطاهم الموهبة كما لنا أيضا بالسوية مؤمنين بالرب يسوع المسيح فمن أنا؟ أقادر أن أمنع الله؟».","11:18":"فلما سمعوا ذلك سكتوا وكانوا يمجدون الله قائلين: «إذا أعطى الله الأمم أيضا التوبة للحياة!».","11:19":"أما الذين تشتتوا من جراء الضيق الذي حصل بسبب إستفانوس فاجتازوا إلى فينيقية وقبرس وأنطاكية وهم لا يكلمون أحدا بالكلمة إلا اليهود فقط.","11:20":"ولكن كان منهم قوم وهم رجال قبرسيون وقيروانيون الذين لما دخلوا أنطاكية كانوا يخاطبون اليونانيين مبشرين بالرب يسوع.","11:21":"وكانت يد الرب معهم فآمن عدد كثير ورجعوا إلى الرب.","11:22":"فسمع الخبر عنهم في آذان الكنيسة التي في أورشليم فأرسلوا برنابا لكي يجتاز إلى أنطاكية.","11:23":"الذي لما أتى ورأى نعمة الله فرح ووعظ الجميع أن يثبتوا في الرب بعزم القلب","11:24":"لأنه كان رجلا صالحا وممتلئا من الروح القدس والإيمان. فانضم إلى الرب جمع غفير.","11:25":"ثم خرج برنابا إلى طرسوس ليطلب شاول. ولما وجده جاء به إلى أنطاكية.","11:26":"فحدث أنهما اجتمعا في الكنيسة سنة كاملة وعلما جمعا غفيرا. ودعي التلاميذ «مسيحيين» في أنطاكية أولا.","11:27":"وفي تلك الأيام انحدر أنبياء من أورشليم إلى أنطاكية.","11:28":"وقام واحد منهم اسمه أغابوس وأشار بالروح أن جوعا عظيما كان عتيدا أن يصير على جميع المسكونة - الذي صار أيضا في أيام كلوديوس قيصر.","11:29":"فحتم التلاميذ حسبما تيسر لكل منهم أن يرسل كل واحد شيئا خدمة إلى الإخوة الساكنين في اليهودية.","11:30":"ففعلوا ذلك مرسلين إلى المشايخ بيد برنابا وشاول.","12:1":"وفي ذلك الوقت مد هيرودس الملك يديه ليسيئ إلى أناس من الكنيسة","12:2":"فقتل يعقوب أخا يوحنا بالسيف.","12:3":"وإذ رأى أن ذلك يرضي اليهود عاد فقبض على بطرس أيضا. وكانت أيام الفطير.","12:4":"ولما أمسكه وضعه في السجن مسلما إياه إلى أربعة أرابع من العسكر ليحرسوه ناويا أن يقدمه بعد الفصح إلى الشعب.","12:5":"فكان بطرس محروسا في السجن وأما الكنيسة فكانت تصير منها صلاة بلجاجة إلى الله من أجله.","12:6":"ولما كان هيرودس مزمعا أن يقدمه كان بطرس في تلك الليلة نائما بين عسكريين مربوطا بسلسلتين وكان قدام الباب حراس يحرسون السجن.","12:7":"وإذا ملاك الرب أقبل ونور أضاء في البيت فضرب جنب بطرس وأيقظه قائلا: «قم عاجلا». فسقطت السلسلتان من يديه.","12:8":"وقال له الملاك: «تمنطق والبس نعليك». ففعل هكذا. فقال له: «البس رداءك واتبعني».","12:9":"فخرج يتبعه - وكان لا يعلم أن الذي جرى بواسطة الملاك هو حقيقي بل يظن أنه ينظر رؤيا.","12:10":"فجازا المحرس الأول والثاني وأتيا إلى باب الحديد الذي يؤدي إلى المدينة فانفتح لهما من ذاته فخرجا وتقدما زقاقا واحدا وللوقت فارقه الملاك.","12:11":"فقال بطرس وهو قد رجع إلى نفسه: «الآن علمت يقينا أن الرب أرسل ملاكه وأنقذني من يد هيرودس ومن كل انتظار شعب اليهود».","12:12":"ثم جاء وهو منتبه إلى بيت مريم أم يوحنا الملقب مرقس حيث كان كثيرون مجتمعين وهم يصلون.","12:13":"فلما قرع بطرس باب الدهليز جاءت جارية اسمها رودا لتسمع.","12:14":"فلما عرفت صوت بطرس لم تفتح الباب من الفرح بل ركضت إلى داخل وأخبرت أن بطرس واقف قدام الباب.","12:15":"فقالوا لها: «أنت تهذين!». وأما هي فكانت تؤكد أن هكذا هو. فقالوا: «إنه ملاكه!».","12:16":"وأما بطرس فلبث يقرع. فلما فتحوا ورأوه اندهشوا.","12:17":"فأشار إليهم بيده ليسكتوا وحدثهم كيف أخرجه الرب من السجن. وقال: «أخبروا يعقوب والإخوة بهذا». ثم خرج وذهب إلى موضع آخر.","12:18":"فلما صار النهار حصل اضطراب ليس بقليل بين العسكر: ترى ماذا جرى لبطرس؟","12:19":"وأما هيرودس فلما طلبه ولم يجده فحص الحراس وأمر أن ينقادوا إلى القتل. ثم نزل من اليهودية إلى قيصرية وأقام هناك.","12:20":"وكان هيرودس ساخطا على الصوريين والصيداويين فحضروا إليه بنفس واحدة واستعطفوا بلاستس الناظر على مضجع الملك ثم صاروا يلتمسون المصالحة لأن كورتهم تقتات من كورة الملك.","12:21":"ففي يوم معين لبس هيرودس الحلة الملوكية وجلس على كرسي الملك وجعل يخاطبهم.","12:22":"فصرخ الشعب: «هذا صوت إله لا صوت إنسان!»","12:23":"ففي الحال ضربه ملاك الرب لأنه لم يعط المجد لله فصار يأكله الدود ومات.","12:24":"وأما كلمة الله فكانت تنمو وتزيد.","12:25":"ورجع برنابا وشاول من أورشليم بعد ما كملا الخدمة وأخذا معهما يوحنا الملقب مرقس.","13:1":"وكان في أنطاكية في الكنيسة هناك أنبياء ومعلمون: برنابا وسمعان الذي يدعى نيجر ولوكيوس القيرواني ومناين الذي تربى مع هيرودس رئيس الربع وشاول.","13:2":"وبينما هم يخدمون الرب ويصومون قال الروح القدس: «أفرزوا لي برنابا وشاول للعمل الذي دعوتهما إليه».","13:3":"فصاموا حينئذ وصلوا ووضعوا عليهما الأيادي ثم أطلقوهما.","13:4":"فهذان إذ أرسلا من الروح القدس انحدرا إلى سلوكية ومن هناك سافرا في البحر إلى قبرس.","13:5":"ولما صارا في سلاميس ناديا بكلمة الله في مجامع اليهود. وكان معهما يوحنا خادما.","13:6":"ولما اجتازا الجزيرة إلى بافوس وجدا رجلا ساحرا نبيا كذابا يهوديا اسمه باريشوع","13:7":"كان مع الوالي سرجيوس بولس وهو رجل فهيم. فهذا دعا برنابا وشاول والتمس أن يسمع كلمة الله.","13:8":"فقاومهما عليم الساحر لأن هكذا يترجم اسمه طالبا أن يفسد الوالي عن الإيمان.","13:9":"وأما شاول الذي هو بولس أيضا فامتلأ من الروح القدس وشخص إليه","13:10":"وقال: «أيها الممتلئ كل غش وكل خبث! يا ابن إبليس! يا عدو كل بر! ألا تزال تفسد سبل الله المستقيمة؟","13:11":"فالآن هوذا يد الرب عليك فتكون أعمى لا تبصر الشمس إلى حين». ففي الحال سقط عليه ضباب وظلمة فجعل يدور ملتمسا من يقوده بيده.","13:12":"فالوالي حينئذ لما رأى ما جرى آمن مندهشا من تعليم الرب.","13:13":"ثم أقلع بولس ومن معه من بافوس وأتوا إلى برجة بمفيلية. وأما يوحنا ففارقهم ورجع إلى أورشليم.","13:14":"وأما هم فجازوا من برجة وأتوا إلى أنطاكية بيسيدية ودخلوا المجمع يوم السبت وجلسوا.","13:15":"وبعد قراءة الناموس والأنبياء أرسل إليهم رؤساء المجمع قائلين: «أيها الرجال الإخوة إن كانت عندكم كلمة وعظ للشعب فقولوا».","13:16":"فقام بولس وأشار بيده وقال: «أيها الرجال الإسرائيليون والذين يتقون الله اسمعوا.","13:17":"إله شعب إسرائيل هذا اختار آباءنا ورفع الشعب في الغربة في أرض مصر وبذراع مرتفعة أخرجهم منها.","13:18":"ونحو مدة أربعين سنة احتمل عوائدهم في البرية.","13:19":"ثم أهلك سبع أمم في أرض كنعان وقسم لهم أرضهم بالقرعة.","13:20":"وبعد ذلك في نحو أربعمئة وخمسين سنة أعطاهم قضاة حتى صموئيل النبي.","13:21":"ومن ثم طلبوا ملكا فأعطاهم الله شاول بن قيس رجلا من سبط بنيامين أربعين سنة.","13:22":"ثم عزله وأقام لهم داود ملكا الذي شهد له أيضا إذ قال: وجدت داود بن يسى رجلا حسب قلبي الذي سيصنع كل مشيئتي.","13:23":"من نسل هذا حسب الوعد أقام الله لإسرائيل مخلصا يسوع.","13:24":"إذ سبق يوحنا فكرز قبل مجيئه بمعمودية التوبة لجميع شعب إسرائيل.","13:25":"ولما صار يوحنا يكمل سعيه جعل يقول: «من تظنون أني أنا؟ لست أنا إياه لكن هوذا يأتي بعدي الذي لست مستحقا أن أحل حذاء قدميه.","13:26":"«أيها الرجال الإخوة بني جنس إبراهيم والذين بينكم يتقون الله إليكم أرسلت كلمة هذا الخلاص.","13:27":"لأن الساكنين في أورشليم ورؤساءهم لم يعرفوا هذا. وأقوال الأنبياء التي تقرأ كل سبت تمموها إذ حكموا عليه.","13:28":"ومع أنهم لم يجدوا علة واحدة للموت طلبوا من بيلاطس أن يقتل.","13:29":"ولما تمموا كل ما كتب عنه أنزلوه عن الخشبة ووضعوه في قبر.","13:30":"ولكن الله أقامه من الأموات.","13:31":"وظهر أياما كثيرة للذين صعدوا معه من الجليل إلى أورشليم الذين هم شهوده عند الشعب.","13:32":"ونحن نبشركم بالموعد الذي صار لآبائنا","13:33":"إن الله قد أكمل هذا لنا نحن أولادهم إذ أقام يسوع كما هو مكتوب أيضا في المزمور الثاني: أنت ابني أنا اليوم ولدتك.","13:34":"إنه أقامه من الأموات غير عتيد أن يعود أيضا إلى فساد فهكذا قال: إني سأعطيكم مراحم داود الصادقة.","13:35":"ولذلك قال أيضا في مزمور آخر:لن تدع قدوسك يرى فسادا.","13:36":"لأن داود بعد ما خدم جيله بمشورة الله رقد وانضم إلى آبائه ورأى فسادا.","13:37":"وأما الذي أقامه الله فلم ير فسادا.","13:38":"فليكن معلوما عندكم أيها الرجال الإخوة أنه بهذا ينادى لكم بغفران الخطايا","13:39":"وبهذا يتبرر كل من يؤمن من كل ما لم تقدروا أن تتبرروا منه بناموس موسى.","13:40":"فانظروا لئلا يأتي عليكم ما قيل في الأنبياء:","13:41":"انظروا أيها المتهاونون وتعجبوا واهلكوا لأنني عملا أعمل في أيامكم عملا لا تصدقون إن أخبركم أحد به».","13:42":"وبعدما خرج اليهود من المجمع جعل الأمم يطلبون إليهما أن يكلماهم بهذا الكلام في السبت القادم.","13:43":"ولما انفضت الجماعة تبع كثيرون من اليهود والدخلاء المتعبدين بولس وبرنابا اللذين كانا يكلمانهم ويقنعانهم أن يثبتوا في نعمة الله.","13:44":"وفي السبت التالي اجتمعت كل المدينة تقريبا لتسمع كلمة الله.","13:45":"فلما رأى اليهود الجموع امتلأوا غيرة وجعلوا يقاومون ما قاله بولس مناقضين ومجدفين.","13:46":"فجاهر بولس وبرنابا وقالا: «كان يجب أن تكلموا أنتم أولا بكلمة الله ولكن إذ دفعتموها عنكم وحكمتم أنكم غير مستحقين للحياة الأبدية هوذا نتوجه إلى الأمم.","13:47":"لأن هكذا أوصانا الرب: قد أقمتك نورا للأمم لتكون أنت خلاصا إلى أقصى الأرض».","13:48":"فلما سمع الأمم ذلك كانوا يفرحون ويمجدون كلمة الرب وآمن جميع الذين كانوا معينين للحياة الأبدية","13:49":"وانتشرت كلمة الرب في كل الكورة.","13:50":"ولكن اليهود حركوا النساء المتعبدات الشريفات ووجوه المدينة وأثاروا اضطهادا على بولس وبرنابا وأخرجوهما من تخومهم.","13:51":"أما هما فنفضا غبار أرجلهما عليهم وأتيا إلى إيقونية.","13:52":"وأما التلاميذ فكانوا يمتلئون من الفرح والروح القدس.","14:1":"وحدث في إيقونية أنهما دخلا معا إلى مجمع اليهود وتكلما حتى آمن جمهور كثير من اليهود واليونانيين.","14:2":"ولكن اليهود غير المؤمنين غروا وأفسدوا نفوس الأمم على الإخوة.","14:3":"فأقاما زمانا طويلا يجاهران بالرب الذي كان يشهد لكلمة نعمته ويعطي أن تجرى آيات وعجائب على أيديهما.","14:4":"فانشق جمهور المدينة فكان بعضهم مع اليهود وبعضهم مع الرسولين.","14:5":"فلما حصل من الأمم واليهود مع رؤسائهم هجوم ليبغوا عليهما ويرجموهما","14:6":"شعرا به فهربا إلى مدينتي ليكأونية: لسترة ودربة وإلى الكورة المحيطة.","14:7":"وكانا هناك يبشران.","14:8":"وكان يجلس في لسترة رجل عاجز الرجلين مقعد من بطن أمه ولم يمش قط.","14:9":"هذا كان يسمع بولس يتكلم فشخص إليه وإذ رأى أن له إيمانا ليشفى","14:10":"قال بصوت عظيم: «قم على رجليك منتصبا». فوثب وصار يمشي.","14:11":"فالجموع لما رأوا ما فعل بولس رفعوا صوتهم بلغة ليكأونية قائلين: «إن الآلهة تشبهوا بالناس ونزلوا إلينا».","14:12":"فكانوا يدعون برنابا «زفس» وبولس «هرمس» إذ كان هو المتقدم في الكلام.","14:13":"فأتى كاهن زفس الذي كان قدام المدينة بثيران وأكاليل عند الأبواب مع الجموع وكان يريد أن يذبح.","14:14":"فلما سمع الرسولان برنابا وبولس مزقا ثيابهما واندفعا إلى الجمع صارخين:","14:15":"«أيها الرجال لماذا تفعلون هذا؟ نحن أيضا بشر تحت آلام مثلكم نبشركم أن ترجعوا من هذه الأباطيل إلى الإله الحي الذي خلق السماء والأرض والبحر وكل ما فيها","14:16":"الذي في الأجيال الماضية ترك جميع الأمم يسلكون في طرقهم -","14:17":"مع أنه لم يترك نفسه بلا شاهد - وهو يفعل خيرا يعطينا من السماء أمطارا وأزمنة مثمرة ويملأ قلوبنا طعاما وسرورا».","14:18":"وبقولهما هذا كفا الجموع بالجهد عن أن يذبحوا لهما.","14:19":"ثم أتى يهود من أنطاكية وإيقونية وأقنعوا الجموع فرجموا بولس وجروه خارج المدينة ظانين أنه قد مات.","14:20":"ولكن إذ أحاط به التلاميذ قام ودخل المدينة وفي الغد خرج مع برنابا إلى دربة.","14:21":"فبشرا في تلك المدينة وتلمذا كثيرين ثم رجعا إلى لسترة وإيقونية وأنطاكية","14:22":"يشددان أنفس التلاميذ ويعظانهم أن يثبتوا في الإيمان وأنه بضيقات كثيرة ينبغي أن ندخل ملكوت الله.","14:23":"وانتخبا لهم قسوسا في كل كنيسة ثم صليا بأصوام واستودعاهم للرب الذي كانوا قد آمنوا به.","14:24":"ولما اجتازا في بيسيدية أتيا إلى بمفيلية","14:25":"وتكلما بالكلمة في برجة ثم نزلا إلى أتالية","14:26":"ومن هناك سافرا في البحر إلى أنطاكية حيث كانا قد أسلما إلى نعمة الله للعمل الذي أكملاه.","14:27":"ولما حضرا وجمعا الكنيسة أخبرا بكل ما صنع الله معهما وأنه فتح للأمم باب الإيمان.","14:28":"وأقاما هناك زمانا ليس بقليل مع التلاميذ.","15:1":"وانحدر قوم من اليهودية وجعلوا يعلمون الإخوة أنه «إن لم تختتنوا حسب عادة موسى لا يمكنكم أن تخلصوا».","15:2":"فلما حصل لبولس وبرنابا منازعة ومباحثة ليست بقليلة معهم رتبوا أن يصعد بولس وبرنابا وأناس آخرون منهم إلى الرسل والمشايخ إلى أورشليم من أجل هذه المسألة.","15:3":"فهؤلاء بعد ما شيعتهم الكنيسة اجتازوا في فينيقية والسامرة يخبرونهم برجوع الأمم وكانوا يسببون سرورا عظيما لجميع الإخوة.","15:4":"ولما حضروا إلى أورشليم قبلتهم الكنيسة والرسل والمشايخ فأخبروهم بكل ما صنع الله معهم.","15:5":"ولكن قام أناس من الذين كانوا قد آمنوا من مذهب الفريسيين وقالوا: «إنه ينبغي أن يختنوا ويوصوا بأن يحفظوا ناموس موسى».","15:6":"فاجتمع الرسل والمشايخ لينظروا في هذا الأمر.","15:7":"فبعد ما حصلت مباحثة كثيرة قام بطرس وقال لهم: «أيها الرجال الإخوة أنتم تعلمون أنه منذ أيام قديمة اختار الله بيننا أنه بفمي يسمع الأمم كلمة الإنجيل ويؤمنون.","15:8":"والله العارف القلوب شهد لهم معطيا لهم الروح القدس كما لنا أيضا.","15:9":"ولم يميز بيننا وبينهم بشيء إذ طهر بالإيمان قلوبهم.","15:10":"فالآن لماذا تجربون الله بوضع نير على عنق التلاميذ لم يستطع آباؤنا ولا نحن أن نحمله؟","15:11":"لكن بنعمة الرب يسوع المسيح نؤمن أن نخلص كما أولئك أيضا».","15:12":"فسكت الجمهور كله. وكانوا يسمعون برنابا وبولس يحدثان بجميع ما صنع الله من الآيات والعجائب في الأمم بواسطتهم.","15:13":"وبعدما سكتا قال يعقوب: «أيها الرجال الإخوة اسمعوني.","15:14":"سمعان قد أخبر كيف افتقد الله أولا الأمم ليأخذ منهم شعبا على اسمه.","15:15":"وهذا توافقه أقوال الأنبياء كما هو مكتوب:","15:16":"سأرجع بعد هذا وأبني أيضا خيمة داود الساقطة وأبني أيضا ردمها وأقيمها ثانية","17:6":"ولما لم يجدوهما جروا ياسون وأناسا من الإخوة إلى حكام المدينة صارخين: «إن هؤلاء الذين فتنوا المسكونة حضروا إلى ههنا أيضا.","17:7":"وقد قبلهم ياسون. وهؤلاء كلهم يعملون ضد أحكام قيصر قائلين إنه يوجد ملك آخر: يسوع!»","17:8":"فأزعجوا الجمع وحكام المدينة إذ سمعوا هذا.","17:9":"فأخذوا كفالة من ياسون ومن الباقين ثم أطلقوهم.","17:10":"وأما الإخوة فللوقت أرسلوا بولس وسيلا ليلا إلى بيرية. وهما لما وصلا مضيا إلى مجمع اليهود.","17:11":"وكان هؤلاء أشرف من الذين في تسالونيكي فقبلوا الكلمة بكل نشاط فاحصين الكتب كل يوم: هل هذه الأمور هكذا؟","17:12":"فآمن منهم كثيرون ومن النساء اليونانيات الشريفات ومن الرجال عدد ليس بقليل.","17:13":"فلما علم اليهود الذين من تسالونيكي أنه في بيرية أيضا نادى بولس بكلمة الله جاءوا يهيجون الجموع هناك أيضا.","17:14":"فحينئذ أرسل الإخوة بولس للوقت ليذهب كما إلى البحر وأما سيلا وتيموثاوس فبقيا هناك.","17:15":"والذين صاحبوا بولس جاءوا به إلى أثينا. ولما أخذوا وصية إلى سيلا وتيموثاوس أن يأتيا إليه بأسرع ما يمكن مضوا.","17:16":"وبينما بولس ينتظرهما في أثينا احتدت روحه فيه إذ رأى المدينة مملوءة أصناما.","17:17":"فكان يكلم في المجمع اليهود المتعبدين والذين يصادفونه في السوق كل يوم.","17:18":"فقابله قوم من الفلاسفة الأبيكوريين والرواقيين وقال بعض: «ترى ماذا يريد هذا المهذار أن يقول؟» وبعض: «إنه يظهر مناديا بآلهة غريبة» - لأنه كان يبشرهم بيسوع والقيامة.","17:19":"فأخذوه وذهبوا به إلى أريوس باغوس قائلين: «هل يمكننا أن نعرف ما هو هذا التعليم الجديد الذي تتكلم به.","17:20":"لأنك تأتي إلى مسامعنا بأمور غريبة فنريد أن نعلم ما عسى أن تكون هذه».","17:21":"أما الأثينيون أجمعون والغرباء المستوطنون فلا يتفرغون لشيء آخر إلا لأن يتكلموا أو يسمعوا شيئا حديثا.","17:22":"فوقف بولس في وسط أريوس باغوس وقال: «أيها الرجال الأثينيون أراكم من كل وجه كأنكم متدينون كثيرا","17:23":"لأنني بينما كنت أجتاز وأنظر إلى معبوداتكم وجدت أيضا مذبحا مكتوبا عليه: «لإله مجهول». فالذي تتقونه وأنتم تجهلونه هذا أنا أنادي لكم به.","17:24":"الإله الذي خلق العالم وكل ما فيه هذا إذ هو رب السماء والأرض لا يسكن في هياكل مصنوعة بالأيادي","17:25":"ولا يخدم بأيادي الناس كأنه محتاج إلى شيء إذ هو يعطي الجميع حياة ونفسا وكل شيء.","17:26":"وصنع من دم واحد كل أمة من الناس يسكنون على كل وجه الأرض وحتم بالأوقات المعينة وبحدود مسكنهم","17:27":"لكي يطلبوا الله لعلهم يتلمسونه فيجدوه مع أنه عن كل واحد منا ليس بعيدا.","17:28":"لأننا به نحيا ونتحرك ونوجد. كما قال بعض شعرائكم أيضا: لأننا أيضا ذريته.","17:29":"فإذ نحن ذرية الله لا ينبغي أن نظن أن اللاهوت شبيه بذهب أو فضة أو حجر نقش صناعة واختراع إنسان.","17:30":"فالله الآن يأمر جميع الناس في كل مكان أن يتوبوا متغاضيا عن أزمنة الجهل.","17:31":"لأنه أقام يوما هو فيه مزمع أن يدين المسكونة بالعدل برجل قد عينه مقدما للجميع إيمانا إذ أقامه من الأموات».","17:32":"ولما سمعوا بالقيامة من الأموات كان البعض يستهزئون والبعض يقولون: «سنسمع منك عن هذا أيضا!».","17:33":"وهكذا خرج بولس من وسطهم.","17:34":"ولكن أناسا التصقوا به وآمنوا منهم ديونيسيوس الأريوباغي وامرأة اسمها دامرس وآخرون معهما.","18:1":"وبعد هذا مضى بولس من أثينا وجاء إلى كورنثوس","18:2":"فوجد يهوديا اسمه أكيلا بنطي الجنس كان قد جاء حديثا من إيطاليا وبريسكلا امرأته - لأن كلوديوس كان قد أمر أن يمضي جميع اليهود من رومية. فجاء إليهما.","18:3":"ولكونه من صناعتهما أقام عندهما وكان يعمل لأنهما كانا في صناعتهما خياميين.","18:4":"وكان يحاج في المجمع كل سبت ويقنع يهودا ويونانيين.","18:5":"ولما انحدر سيلا وتيموثاوس من مكدونية كان بولس منحصرا بالروح وهو يشهد لليهود بالمسيح يسوع.","18:6":"وإذ كانوا يقاومون ويجدفون نفض ثيابه وقال لهم: «دمكم على رؤوسكم. أنا بريء. من الآن أذهب إلى الأمم».","18:7":"فانتقل من هناك وجاء إلى بيت رجل اسمه يوستس كان متعبدا لله وكان بيته ملاصقا للمجمع.","18:8":"وكريسبس رئيس المجمع آمن بالرب مع جميع بيته وكثيرون من الكورنثيين إذ سمعوا آمنوا واعتمدوا.","18:9":"فقال الرب لبولس برؤيا في الليل: «لا تخف بل تكلم ولا تسكت","18:10":"لأني أنا معك ولا يقع بك أحد ليؤذيك لأن لي شعبا كثيرا في هذه المدينة».","18:11":"فأقام سنة وستة أشهر يعلم بينهم بكلمة الله.","18:12":"ولما كان غاليون يتولى أخائية قام اليهود بنفس واحدة على بولس وأتوا به إلى كرسي الولاية","18:13":"قائلين: «إن هذا يستميل الناس أن يعبدوا الله بخلاف الناموس».","18:14":"وإذ كان بولس مزمعا أن يتكلم قال غاليون لليهود: «لو كان ظلما أو خبثا رديا أيها اليهود لكنت بالحق قد احتملتكم.","18:15":"ولكن إذا كان مسألة عن كلمة وأسماء وناموسكم فتبصرون أنتم. لأني لست أشاء أن أكون قاضيا لهذه الأمور».","18:16":"فطردهم من الكرسي.","18:17":"فأخذ جميع اليونانيين سوستانيس رئيس المجمع وضربوه قدام الكرسي ولم يهم غاليون شيء من ذلك.","18:18":"وأما بولس فلبث أيضا أياما كثيرة ثم ودع الإخوة وسافر في البحر إلى سورية ومعه بريسكلا وأكيلا بعدما حلق رأسه في كنخريا - لأنه كان عليه نذر.","18:19":"فأقبل إلى أفسس وتركهما هناك. وأما هو فدخل المجمع وحاج اليهود.","18:20":"وإذ كانوا يطلبون أن يمكث عندهم زمانا أطول لم يجب.","18:21":"بل ودعهم قائلا: «ينبغي على كل حال أن أعمل العيد القادم في أورشليم. ولكن سأرجع إليكم أيضا إن شاء الله». فأقلع من أفسس.","18:22":"ولما نزل في قيصرية صعد وسلم على الكنيسة ثم انحدر إلى أنطاكية.","18:23":"وبعدما صرف زمانا خرج واجتاز بالتتابع في كورة غلاطية وفريجية يشدد جميع التلاميذ.","18:24":"ثم أقبل إلى أفسس يهودي اسمه أبلوس إسكندري الجنس رجل فصيح مقتدر في الكتب.","18:25":"كان هذا خبيرا في طريق الرب. وكان وهو حار بالروح يتكلم ويعلم بتدقيق ما يختص بالرب. عارفا معمودية يوحنا فقط.","18:26":"وابتدأ هذا يجاهر في المجمع. فلما سمعه أكيلا وبريسكلا أخذاه إليهما وشرحا له طريق الرب بأكثر تدقيق.","18:27":"وإذ كان يريد أن يجتاز إلى أخائية كتب الإخوة إلى التلاميذ يحضونهم أن يقبلوه. فلما جاء ساعد كثيرا بالنعمة الذين كانوا قد آمنوا","18:28":"لأنه كان باشتداد يفحم اليهود جهرا مبينا بالكتب أن يسوع هو المسيح.","19:1":"فحدث فيما كان أبلوس في كورنثوس أن بولس بعد ما اجتاز في النواحي العالية جاء إلى أفسس. فإذ وجد تلاميذ","19:2":"سألهم: «هل قبلتم الروح القدس لما آمنتم؟» قالوا له: «ولا سمعنا أنه يوجد الروح القدس».","19:3":"فسألهم: «فبماذا اعتمدتم؟» فقالوا: «بمعمودية يوحنا».","19:4":"فقال بولس: «إن يوحنا عمد بمعمودية التوبة قائلا للشعب أن يؤمنوا بالذي يأتي بعده أي بالمسيح يسوع».","19:5":"فلما سمعوا اعتمدوا باسم الرب يسوع.","19:6":"ولما وضع بولس يديه عليهم حل الروح القدس عليهم فطفقوا يتكلمون بلغات ويتنبأون.","19:7":"وكان جميع الرجال نحو اثني عشر.","19:8":"ثم دخل المجمع وكان يجاهر مدة ثلاثة أشهر محاجا ومقنعا في ما يختص بملكوت الله.","19:9":"ولما كان قوم يتقسون ولا يقنعون شاتمين الطريق أمام الجمهور اعتزل عنهم وأفرز التلاميذ محاجا كل يوم في مدرسة إنسان اسمه تيرانس -","19:10":"وكان ذلك مدة سنتين حتى سمع كلمة الرب يسوع جميع الساكنين في أسيا من يهود ويونانيين.","19:11":"وكان الله يصنع على يدي بولس قوات غير المعتادة","19:12":"حتى كان يؤتى عن جسده بمناديل أو مآزر إلى المرضى فتزول عنهم الأمراض وتخرج الأرواح الشريرة منهم.","19:13":"فشرع قوم من اليهود الطوافين المعزمين أن يسموا على الذين بهم الأرواح الشريرة باسم الرب يسوع قائلين: «نقسم عليك بيسوع الذي يكرز به بولس!»","19:14":"وكان الذين فعلوا هذا سبعة بنين لسكاوا رجل يهودي رئيس كهنة.","19:15":"فقال الروح الشرير لهم: «أما يسوع فأنا أعرفه وبولس أنا أعلمه وأما أنتم فمن أنتم؟»","19:16":"فوثب عليهم الإنسان الذي كان فيه الروح الشرير وغلبهم وقوي عليهم حتى هربوا من ذلك البيت عراة ومجرحين.","19:17":"وصار هذا معلوما عند جميع اليهود واليونانيين الساكنين في أفسس. فوقع خوف على جميعهم وكان اسم الرب يسوع يتعظم.","19:18":"وكان كثيرون من الذين آمنوا يأتون مقرين ومخبرين بأفعالهم","19:19":"وكان كثيرون من الذين يستعملون السحر يجمعون الكتب ويحرقونها أمام الجميع. وحسبوا أثمانها فوجدوها خمسين ألفا من الفضة.","19:20":"هكذا كانت كلمة الرب تنمو وتقوى بشدة.","19:21":"ولما كملت هذه الأمور وضع بولس في نفسه أنه بعدما يجتاز في مكدونية وأخائية يذهب إلى أورشليم قائلا: «إني بعد ما أصير هناك ينبغي أن أرى رومية أيضا».","19:22":"فأرسل إلى مكدونية اثنين من الذين كانوا يخدمونه: تيموثاوس وأرسطوس ولبث هو زمانا في أسيا.","19:23":"وحدث في ذلك الوقت شغب ليس بقليل بسبب هذا الطريق","19:24":"لأن إنسانا اسمه ديمتريوس صائغ صانع هياكل فضة لأرطاميس كان يكسب الصناع مكسبا ليس بقليل.","19:25":"فجمعهم والفعلة في مثل ذلك العمل وقال: «أيها الرجال أنتم تعلمون أن سعتنا إنما هي من هذه الصناعة.","19:26":"وأنتم تنظرون وتسمعون أنه ليس من أفسس فقط بل من جميع أسيا تقريبا استمال وأزاغ بولس هذا جمعا كثيرا قائلا: إن التي تصنع بالأيادي ليست آلهة.","19:27":"فليس نصيبنا هذا وحده في خطر من أن يحصل في إهانة بل أيضا هيكل أرطاميس - الإلهة العظيمة - أن يحسب لا شيء وأن سوف تهدم عظمتها هي التي يعبدها جميع أسيا والمسكونة».","19:28":"فلما سمعوا امتلأوا غضبا وطفقوا يصرخون قائلين: «عظيمة هي أرطاميس الأفسسيين».","19:29":"فامتلأت المدينة كلها اضطرابا واندفعوا بنفس واحدة إلى المشهد خاطفين معهم غايوس وأرسترخس المكدونيين رفيقي بولس في السفر.","19:30":"ولما كان بولس يريد أن يدخل بين الشعب لم يدعه التلاميذ.","19:31":"وأناس من وجوه أسيا - كانوا أصدقاءه - أرسلوا يطلبون إليه أن لا يسلم نفسه إلى المشهد.","19:32":"وكان البعض يصرخون بشيء والبعض بشيء آخر لأن المحفل كان مضطربا وأكثرهم لا يدرون لأي شيء كانوا قد اجتمعوا!","19:33":"فاجتذبوا إسكندر من الجمع وكان اليهود يدفعونه. فأشار إسكندر بيده يريد أن يحتج للشعب.","19:34":"فلما عرفوا أنه يهودي صار صوت واحد من الجميع صارخين نحو مدة ساعتين: «عظيمة هي أرطاميس الأفسسيين!».","19:35":"ثم سكن الكاتب الجمع وقال: «أيها الرجال الأفسسيون من هو الإنسان الذي لا يعلم أن مدينة الأفسسيين متعبدة لأرطاميس الإلهة العظيمة والتمثال الذي هبط من زفس؟","19:36":"فإذ كانت هذه الأشياء لا تقاوم ينبغي أن تكونوا هادئين ولا تفعلوا شيئا اقتحاما.","19:37":"لأنكم أتيتم بهذين الرجلين وهما ليسا سارقي هياكل ولا مجدفين على إلهتكم.","19:38":"فإن كان ديمتريوس والصناع الذين معه لهم دعوى على أحد فإنه تقام أيام للقضاء ويوجد ولاة فليرافعوا بعضهم بعضا.","19:39":"وإن كنتم تطلبون شيئا من جهة أمور أخر فإنه يقضى في محفل شرعي.","19:40":"لأننا في خطر أن نحاكم من أجل فتنة هذا اليوم. وليس علة يمكننا من أجلها أن نقدم حسابا عن هذا التجمع».","19:41":"ولما قال هذا صرف المحفل.","20:1":"وبعدما انتهى الشغب دعا بولس التلاميذ وودعهم وخرج ليذهب إلى مكدونية.","20:2":"ولما كان قد اجتاز في تلك النواحي ووعظهم بكلام كثير جاء إلى هلاس","20:3":"فصرف ثلاثة أشهر. ثم إذ حصلت مكيدة من اليهود عليه - وهو مزمع أن يصعد إلى سورية - صار رأي أن يرجع على طريق مكدونية.","20:4":"فرافقه إلى أسيا سوباترس البيري ومن أهل تسالونيكي: أرسترخس وسكوندس وغايس الدربي وتيموثاوس. ومن أهل أسيا: تيخيكس وتروفيمس.","20:5":"هؤلاء سبقوا وانتظرونا في ترواس.","20:6":"وأما نحن فسافرنا في البحر بعد أيام الفطير من فيلبي ووافيناهم في خمسة أيام إلى ترواس حيث صرفنا سبعة أيام.","20:7":"وفي أول الأسبوع إذ كان التلاميذ مجتمعين ليكسروا خبزا خاطبهم بولس وهو مزمع أن يمضي في الغد وأطال الكلام إلى نصف الليل.","20:8":"وكانت مصابيح كثيرة في العلية التي كانوا مجتمعين فيها.","20:9":"وكان شاب اسمه أفتيخوس جالسا في الطاقة متثقلا بنوم عميق. وإذ كان بولس يخاطب خطابا طويلا غلب عليه النوم فسقط من الطبقة الثالثة إلى أسفل وحمل ميتا.","20:10":"فنزل بولس ووقع عليه واعتنقه قائلا: «لا تضطربوا لأن نفسه فيه».","20:11":"ثم صعد وكسر خبزا وأكل وتكلم كثيرا إلى الفجر. وهكذا خرج.","20:12":"وأتوا بالفتى حيا وتعزوا تعزية ليست بقليلة.","20:13":"وأما نحن فسبقنا إلى السفينة وأقلعنا إلى أسوس مزمعين أن نأخذ بولس من هناك لأنه كان قد رتب هكذا مزمعا أن يمشي.","20:14":"فلما وافانا إلى أسوس أخذناه وأتينا إلى ميتيليني.","20:15":"ثم سافرنا من هناك في البحر وأقبلنا في الغد إلى مقابل خيوس. وفي اليوم الآخر وصلنا إلى ساموس وأقمنا في تروجيليون ثم في اليوم التالي جئنا إلى ميليتس","20:16":"لأن بولس عزم أن يتجاوز أفسس في البحر لئلا يعرض له أن يصرف وقتا في أسيا لأنه كان يسرع حتى إذا أمكنه يكون في أورشليم في يوم الخمسين.","20:17":"ومن ميليتس أرسل إلى أفسس واستدعى قسوس الكنيسة.","20:18":"فلما جاءوا إليه قال لهم: «أنتم تعلمون من أول يوم دخلت أسيا كيف كنت معكم كل الزمان","20:19":"أخدم الرب بكل تواضع ودموع كثيرة وبتجارب أصابتني بمكايد اليهود.","20:20":"كيف لم أؤخر شيئا من الفوائد إلا وأخبرتكم وعلمتكم به جهرا وفي كل بيت","20:21":"شاهدا لليهود واليونانيين بالتوبة إلى الله والإيمان الذي بربنا يسوع المسيح.","20:22":"والآن ها أنا أذهب إلى أورشليم مقيدا بالروح لا أعلم ماذا يصادفني هناك.","20:23":"غير أن الروح القدس يشهد في كل مدينة قائلا: إن وثقا وشدائد تنتظرني.","20:24":"ولكنني لست أحتسب لشيء ولا نفسي ثمينة عندي حتى أتمم بفرح سعيي والخدمة التي أخذتها من الرب يسوع لأشهد ببشارة نعمة الله.","20:25":"والآن ها أنا أعلم أنكم لا ترون وجهي أيضا أنتم جميعا الذين مررت بينكم كارزا بملكوت الله.","20:26":"لذلك أشهدكم اليوم هذا أني بريء من دم الجميع","20:27":"لأني لم أؤخر أن أخبركم بكل مشورة الله.","20:28":"احترزوا اذا لأنفسكم ولجميع الرعية التي أقامكم الروح القدس فيها أساقفة لترعوا كنيسة الله التي اقتناها بدمه.","20:29":"لأني أعلم هذا: أنه بعد ذهابي سيدخل بينكم ذئاب خاطفة لا تشفق على الرعية.","20:30":"ومنكم أنتم سيقوم رجال يتكلمون بأمور ملتوية ليجتذبوا التلاميذ وراءهم.","20:31":"لذلك اسهروا متذكرين أني ثلاث سنين ليلا ونهارا لم أفتر عن أن أنذر بدموع كل واحد.","20:32":"والآن أستودعكم يا إخوتي لله ولكلمة نعمته القادرة أن تبنيكم وتعطيكم ميراثا مع جميع المقدسين.","20:33":"فضة أو ذهب أو لباس أحد لم أشته.","20:34":"أنتم تعلمون أن حاجاتي وحاجات الذين معي خدمتها هاتان اليدان.","20:35":"في كل شيء أريتكم أنه هكذا ينبغي أنكم تتعبون وتعضدون الضعفاء متذكرين كلمات الرب يسوع أنه قال: مغبوط هو العطاء أكثر من الأخذ».","20:36":"ولما قال هذا جثا على ركبتيه مع جميعهم وصلى.","20:37":"وكان بكاء عظيم من الجميع ووقعوا على عنق بولس يقبلونه","20:38":"متوجعين ولا سيما من الكلمة التي قالها: إنهم لن يروا وجهه أيضا. ثم شيعوه إلى السفينة.","21:1":"ولما انفصلنا عنهم أقلعنا وجئنا متوجهين بالاستقامة إلى كوس وفي اليوم التالي إلى رودس ومن هناك إلى باترا.","21:2":"فإذ وجدنا سفينة عابرة إلى فينيقية صعدنا إليها وأقلعنا.","21:3":"ثم اطلعنا على قبرس وتركناها يسرة وسافرنا إلى سورية وأقبلنا إلى صور لأن هناك كانت السفينة تضع وسقها.","21:4":"وإذ وجدنا التلاميذ مكثنا هناك سبعة أيام. وكانوا يقولون لبولس بالروح أن لا يصعد إلى أورشليم.","21:5":"ولكن لما استكملنا الأيام خرجنا ذاهبين وهم جميعا يشيعوننا مع النساء والأولاد إلى خارج المدينة. فجثونا على ركبنا على الشاطئ وصلينا.","21:6":"ولما ودعنا بعضنا بعضا صعدنا إلى السفينة. وأما هم فرجعوا إلى خاصتهم.","21:7":"ولما أكملنا السفر في البحر من صور أقبلنا إلى بتولمايس فسلمنا على الإخوة ومكثنا عندهم يوما واحدا.","21:8":"ثم خرجنا في الغد نحن رفقاء بولس وجئنا إلى قيصرية فدخلنا بيت فيلبس المبشر إذ كان واحدا من السبعة وأقمنا عنده.","21:9":"وكان لهذا أربع بنات عذارى كن يتنبأن.","21:10":"وبينما نحن مقيمون أياما كثيرة انحدر من اليهودية نبي اسمه أغابوس.","21:11":"فجاء إلينا وأخذ منطقة بولس وربط يدي نفسه ورجليه وقال: «هذا يقوله الروح القدس: الرجل الذي له هذه المنطقة هكذا سيربطه اليهود في أورشليم ويسلمونه إلى أيدي الأمم».","21:12":"فلما سمعنا هذا طلبنا إليه نحن والذين من المكان أن لا يصعد إلى أورشليم.","21:13":"فأجاب بولس: «ماذا تفعلون؟ تبكون وتكسرون قلبي. لأني مستعد ليس أن أربط فقط بل أن أموت أيضا في أورشليم لأجل اسم الرب يسوع».","21:14":"ولما لم يقنع سكتنا قائلين: «لتكن مشيئة الرب».","21:15":"وبعد تلك الأيام تأهبنا وصعدنا إلى أورشليم.","21:16":"وجاء أيضا معنا من قيصرية أناس من التلاميذ ذاهبين بنا إلى مناسون وهو رجل قبرسي تلميذ قديم لننزل عنده.","21:17":"ولما وصلنا إلى أورشليم قبلنا الإخوة بفرح.","21:18":"وفي الغد دخل بولس معنا إلى يعقوب وحضر جميع المشايخ.","21:19":"فبعد ما سلم عليهم طفق يحدثهم شيئا فشيئا بكل ما فعله الله بين الأمم بواسطة خدمته.","21:20":"فلما سمعوا كانوا يمجدون الرب. وقالوا له: «أنت ترى أيها الأخ كم يوجد ربوة من اليهود الذين آمنوا وهم جميعا غيورون للناموس.","21:21":"وقد أخبروا عنك أنك تعلم جميع اليهود الذين بين الأمم الارتداد عن موسى قائلا أن لا يختنوا أولادهم ولا يسلكوا حسب العوائد.","21:22":"فإذا ماذا يكون؟ لا بد على كل حال أن يجتمع الجمهور لأنهم سيسمعون أنك قد جئت.","21:23":"فافعل هذا الذي نقول لك: عندنا أربعة رجال عليهم نذر.","21:24":"خذ هؤلاء وتطهر معهم وأنفق عليهم ليحلقوا رؤوسهم فيعلم الجميع أن ليس شيء مما أخبروا عنك بل تسلك أنت أيضا حافظا للناموس.","21:25":"وأما من جهة الذين آمنوا من الأمم فأرسلنا نحن إليهم وحكمنا أن لا يحفظوا شيئا مثل ذلك سوى أن يحافظوا على أنفسهم مما ذبح للأصنام ومن الدم والمخنوق والزنا».","21:26":"حينئذ أخذ بولس الرجال في الغد وتطهر معهم ودخل الهيكل مخبرا بكمال أيام التطهير إلى أن يقرب عن كل واحد منهم القربان.","21:27":"ولما قاربت الأيام السبعة أن تتم رآه اليهود الذين من أسيا في الهيكل فأهاجوا كل الجمع وألقوا عليه الأيادي","21:28":"صارخين: «يا أيها الرجال الإسرائيليون أعينوا! هذا هو الرجل الذي يعلم الجميع في كل مكان ضدا للشعب والناموس وهذا الموضع حتى أدخل يونانيين أيضا إلى الهيكل ودنس هذا الموضع المقدس».","21:29":"لأنهم كانوا قد رأوا معه في المدينة تروفيمس الأفسسي فكانوا يظنون أن بولس أدخله إلى الهيكل.","21:30":"فهاجت المدينة كلها وتراكض الشعب وأمسكوا بولس وجروه خارج الهيكل. وللوقت أغلقت الأبواب.","21:31":"وبينما هم يطلبون أن يقتلوه نما خبر إلى أمير الكتيبة أن أورشليم كلها قد اضطربت","21:32":"فللوقت أخذ عسكرا وقواد مئات وركض إليهم. فلما رأوا الأمير والعسكر كفوا عن ضرب بولس.","21:33":"حينئذ اقترب الأمير وأمسكه وأمر أن يقيد بسلسلتين وطفق يستخبر: ترى من يكون وماذا فعل؟","21:34":"وكان البعض يصرخون بشيء والبعض بشيء آخر في الجمع. ولما لم يقدر أن يعلم اليقين لسبب الشغب أمر أن يذهب به إلى المعسكر.","21:35":"ولما صار على الدرج اتفق أن العسكر حمله بسبب عنف الجمع","21:36":"لأن جمهور الشعب كانوا يتبعونه صارخين: «خذه!».","21:37":"وإذ قارب بولس أن يدخل المعسكر قال للأمير: «أيجوز لي أن أقول لك شيئا؟» فقال: «أتعرف اليونانية؟","21:38":"أفلست أنت المصري الذي صنع قبل هذه الأيام فتنة وأخرج إلى البرية أربعة الآلاف الرجل من القتلة؟».","21:39":"فقال بولس: «أنا رجل يهودي طرسوسي من أهل مدينة غير دنية من كيليكية. وألتمس منك أن تأذن لي أن أكلم الشعب».","21:40":"فلما أذن له وقف بولس على الدرج وأشار بيده إلى الشعب فصار سكوت عظيم. فنادى باللغة العبرانية قائلا:","22:1":"«أيها الرجال الإخوة والآباء اسمعوا احتجاجي الآن لديكم».","22:2":"فلما سمعوا أنه ينادي لهم باللغة العبرانية أعطوا سكوتا أحرى. فقال:","22:3":"«أنا رجل يهودي ولدت في طرسوس كيليكية ولكن ربيت في هذه المدينة مؤدبا عند رجلي غمالائيل على تحقيق الناموس الأبوي. وكنت غيورا لله كما أنتم جميعكم اليوم.","22:4":"واضطهدت هذا الطريق حتى الموت مقيدا ومسلما إلى السجون رجالا ونساء","22:5":"كما يشهد لي أيضا رئيس الكهنة وجميع المشيخة الذين إذ أخذت أيضا منهم رسائل للإخوة إلى دمشق ذهبت لآتي بالذين هناك إلى أورشليم مقيدين لكي يعاقبوا.","22:6":"فحدث لي وأنا ذاهب ومتقرب إلى دمشق أنه نحو نصف النهار بغتة أبرق حولي من السماء نور عظيم.","22:7":"فسقطت على الأرض وسمعت صوتا قائلا لي: شاول شاول لماذا تضطهدني؟","22:8":"فأجبت: من أنت يا سيد؟ فقال لي: أنا يسوع الناصري الذي أنت تضطهده.","22:9":"والذين كانوا معي نظروا النور وارتعبوا ولكنهم لم يسمعوا صوت الذي كلمني.","22:10":"فقلت: ماذا أفعل يا رب؟ فقال لي الرب: قم واذهب إلى دمشق وهناك يقال لك عن جميع ما ترتب لك أن تفعل.","22:11":"وإذ كنت لا أبصر من أجل بهاء ذلك النور اقتادني بيدي الذين كانوا معي فجئت إلى دمشق.","22:12":"«ثم إن حنانيا رجلا تقيا حسب الناموس ومشهودا له من جميع اليهود السكان","22:13":"أتى إلي ووقف وقال لي: أيها الأخ شاول أبصر! ففي تلك الساعة نظرت إليه","22:14":"فقال: إله آبائنا انتخبك لتعلم مشيئته وتبصر البار وتسمع صوتا من فمه.","22:15":"لأنك ستكون له شاهدا لجميع الناس بما رأيت وسمعت.","22:16":"والآن لماذا تتوانى؟ قم واعتمد واغسل خطاياك داعيا باسم الرب.","22:17":"وحدث لي بعد ما رجعت إلى أورشليم وكنت أصلي في الهيكل أني حصلت في غيبة","22:18":"فرأيته قائلا لي: أسرع واخرج عاجلا من أورشليم لأنهم لا يقبلون شهادتك عني.","22:19":"فقلت: يا رب هم يعلمون أني كنت أحبس وأضرب في كل مجمع الذين يؤمنون بك.","22:20":"وحين سفك دم استفانوس شهيدك كنت أنا واقفا وراضيا بقتله وحافظا ثياب الذين قتلوه.","22:21":"فقال لي: اذهب فإني سأرسلك إلى الأمم بعيدا».","22:22":"فسمعوا له حتى هذه الكلمة ثم صرخوا قائلين: «خذ مثل هذا من الأرض لأنه كان لا يجوز أن يعيش».","22:23":"وإذ كانوا يصيحون ويطرحون ثيابهم ويرمون غبارا إلى الجو","22:24":"أمر الأمير أن يذهب به إلى المعسكر قائلا أن يفحص بضربات ليعلم لأي سبب كانوا يصرخون عليه هكذا.","22:25":"فلما مدوه للسياط قال بولس لقائد المئة الواقف: «أيجوز لكم أن تجلدوا إنسانا رومانيا غير مقضي عليه؟»","22:26":"فإذ سمع قائد المئة ذهب إلى الأمير وأخبره قائلا: «انظر ماذا أنت مزمع أن تفعل! لأن هذا الرجل روماني».","22:27":"فجاء الأمير وقال له: «قل لي. أأنت روماني؟» فقال: «نعم».","22:28":"فأجاب الأمير: «أما أنا فبمبلغ كبير اقتنيت هذه الرعوية». فقال بولس: «أما أنا فقد ولدت فيها».","22:29":"وللوقت تنحى عنه الذين كانوا مزمعين أن يفحصوه. واختشى الأمير لما علم أنه روماني ولأنه قد قيده.","22:30":"وفي الغد إذ كان يريد أن يعلم اليقين: لماذا يشتكي اليهود عليه؟ حله من الرباط وأمر أن يحضر رؤساء الكهنة وكل مجمعهم. فأحضر بولس وأقامه لديهم.","23:1":"فتفرس بولس في المجمع وقال: «أيها الرجال الإخوة إني بكل ضمير صالح قد عشت لله إلى هذا اليوم».","23:2":"فأمر حنانيا رئيس الكهنة الواقفين عنده أن يضربوه على فمه.","23:3":"حينئذ قال له بولس: «سيضربك الله أيها الحائط المبيض! أفأنت جالس تحكم علي حسب الناموس وأنت تأمر بضربي مخالفا للناموس؟»","23:4":"فقال الواقفون: «أتشتم رئيس كهنة الله؟»","23:5":"فقال بولس: «لم أكن أعرف أيها الإخوة أنه رئيس كهنة لأنه مكتوب: رئيس شعبك لا تقل فيه سوءا».","23:6":"ولما علم بولس أن قسما منهم صدوقيون والآخر فريسيون صرخ في المجمع: «أيها الرجال الإخوة أنا فريسي ابن فريسي. على رجاء قيامة الأموات أنا أحاكم».","23:7":"ولما قال هذا حدثت منازعة بين الفريسيين والصدوقيين وانشقت الجماعة","23:8":"لأن الصدوقيين يقولون إنه ليس قيامة ولا ملاك ولا روح وأما الفريسيون فيقرون بكل ذلك.","23:9":"فحدث صياح عظيم ونهض كتبة قسم الفريسيين وطفقوا يخاصمون قائلين: «لسنا نجد شيئا رديا في هذا الإنسان! وإن كان روح أو ملاك قد كلمه فلا نحاربن الله».","23:10":"ولما حدثت منازعة كثيرة اختشى الأمير أن يفسخوا بولس فأمر العسكر أن ينزلوا ويختطفوه من وسطهم ويأتوا به إلى المعسكر.","23:11":"وفي الليلة التالية وقف به الرب وقال: «ثق يا بولس لأنك كما شهدت بما لي في أورشليم هكذا ينبغي أن تشهد في رومية أيضا».","23:12":"ولما صار النهار صنع بعض اليهود اتفاقا وحرموا أنفسهم قائلين إنهم لا يأكلون ولا يشربون حتى يقتلوا بولس.","23:13":"وكان الذين صنعوا هذا التحالف أكثر من أربعين.","23:14":"فتقدموا إلى رؤساء الكهنة والشيوخ وقالوا: «قد حرمنا أنفسنا حرما أن لا نذوق شيئا حتى نقتل بولس.","23:15":"والآن أعلموا الأمير أنتم مع المجمع لكي ينزله إليكم غدا كأنكم مزمعون أن تفحصوا بأكثر تدقيق عما له. ونحن قبل أن يقترب مستعدون لقتله».","23:16":"ولكن ابن أخت بولس سمع بالكمين فجاء ودخل المعسكر وأخبر بولس.","23:17":"فاستدعى بولس واحدا من قواد المئات وقال: «اذهب بهذا الشاب إلى الأمير لأن عنده شيئا يخبره به».","23:18":"فأخذه وأحضره إلى الأمير وقال: «استدعاني الأسير بولس وطلب أن أحضر هذا الشاب إليك وهو عنده شيء ليقوله لك».","23:19":"فأخذ الأمير بيده وتنحى به منفردا واستخبره: «ما هو الذي عندك لتخبرني به؟»","23:20":"فقال: «إن اليهود تعاهدوا أن يطلبوا منك أن تنزل بولس غدا إلى المجمع كأنهم مزمعون أن يستخبروا عنه بأكثر تدقيق.","23:21":"فلا تنقد إليهم لأن أكثر من أربعين رجلا منهم كامنون له قد حرموا أنفسهم أن لا يأكلوا ولا يشربوا حتى يقتلوه. وهم الآن مستعدون منتظرون الوعد منك».","23:22":"فأطلق الأمير الشاب موصيا إياه أن: «لا تقل لأحد إنك أعلمتني بهذا».","23:23":"ثم دعا اثنين من قواد المئات وقال: «أعدا مئتي عسكري ليذهبوا إلى قيصرية وسبعين فارسا ومئتي رامح من الساعة الثالثة من الليل.","23:24":"وأن يقدما دواب ليركبا بولس ويوصلاه سالما إلى فيلكس الوالي».","23:25":"وكتب رسالة حاوية هذه الصورة:","23:26":"«كلوديوس ليسياس يهدي سلاما إلى العزيز فيلكس الوالي.","23:27":"هذا الرجل لما أمسكه اليهود وكانوا مزمعين أن يقتلوه أقبلت مع العسكر وأنقذته إذ أخبرت أنه روماني.","23:28":"وكنت أريد أن أعلم العلة التي لأجلها كانوا يشتكون عليه فأنزلته إلى مجمعهم","23:29":"فوجدته مشكوا عليه من جهة مسائل ناموسهم. ولكن شكوى تستحق الموت أو القيود لم تكن عليه.","23:30":"ثم لما أعلمت بمكيدة عتيدة أن تصير على الرجل من اليهود أرسلته للوقت إليك آمرا المشتكين أيضا أن يقولوا لديك ما عليه. كن معافى».","23:31":"فالعسكر أخذوا بولس كما أمروا وذهبوا به ليلا إلى أنتيباتريس.","23:32":"وفي الغد تركوا الفرسان يذهبون معه ورجعوا إلى المعسكر.","23:33":"وأولئك لما دخلوا قيصرية ودفعوا الرسالة إلى الوالي أحضروا بولس أيضا إليه.","23:34":"فلما قرأ الوالي الرسالة وسأل من أية ولاية هو ووجد أنه من كيليكية","23:35":"قال: «سأسمعك متى حضر المشتكون عليك أيضا». وأمر أن يحرس في قصر هيرودس.","24:1":"وبعد خمسة أيام انحدر حنانيا رئيس الكهنة مع الشيوخ وخطيب اسمه ترتلس. فعرضوا للوالي ضد بولس.","24:2":"فلما دعي ابتدأ ترتلس في الشكاية قائلا:","24:3":"«إننا حاصلون بواسطتك على سلام جزيل وقد صارت لهذه الأمة مصالح بتدبيرك. فنقبل ذلك أيها العزيز فيلكس بكل شكر في كل زمان وكل مكان.","24:4":"ولكن لئلا أعوقك أكثر ألتمس أن تسمعنا بالاختصار بحلمك.","24:5":"فإننا إذ وجدنا هذا الرجل مفسدا ومهيج فتنة بين جميع اليهود الذين في المسكونة ومقدام شيعة الناصريين","24:6":"وقد شرع أن ينجس الهيكل أيضا أمسكناه وأردنا أن نحكم عليه حسب ناموسنا.","24:7":"فأقبل ليسياس الأمير بعنف شديد وأخذه من بين أيدينا","24:8":"وأمر المشتكين عليه أن يأتوا إليك. ومنه يمكنك إذا فحصت أن تعلم جميع هذه الأمور التي نشتكي بها عليه».","24:9":"ثم وافقه اليهود أيضا قائلين: «إن هذه الأمور هكذا».","24:10":"فأجاب بولس إذ أومأ إليه الوالي أن يتكلم: «إني إذ قد علمت أنك منذ سنين كثيرة قاض لهذه الأمة أحتج عما في أمري بأكثر سرور.","24:11":"وأنت قادر أن تعرف أنه ليس لي أكثر من اثني عشر يوما منذ صعدت لأسجد في أورشليم.","24:12":"ولم يجدوني في الهيكل أحاج أحدا أو أصنع تجمعا من الشعب ولا في المجامع ولا في المدينة.","24:13":"ولا يستطيعون أن يثبتوا ما يشتكون به الآن علي.","24:14":"ولكنني أقر لك بهذا: أنني حسب الطريق الذي يقولون له «شيعة» هكذا أعبد إله آبائي مؤمنا بكل ما هو مكتوب في الناموس والأنبياء.","24:15":"ولي رجاء بالله في ما هم أيضا ينتظرونه: أنه سوف تكون قيامة للأموات الأبرار والأثمة.","24:16":"لذلك أنا أيضا أدرب نفسي ليكون لي دائما ضمير بلا عثرة من نحو الله والناس.","24:17":"وبعد سنين كثيرة جئت أصنع صدقات لأمتي وقرابين.","24:18":"وفي ذلك وجدني متطهرا في الهيكل - ليس مع جمع ولا مع شغب - قوم هم يهود من أسيا","24:19":"كان ينبغي أن يحضروا لديك ويشتكوا إن كان لهم علي شيء.","24:20":"أو ليقل هؤلاء أنفسهم ماذا وجدوا في من الذنب وأنا قائم أمام المجمع","24:21":"إلا من جهة هذا القول الواحد الذي صرخت به واقفا بينهم: أني من أجل قيامة الأموات أحاكم منكم اليوم».","24:22":"فلما سمع هذا فيلكس أمهلهم إذ كان يعلم بأكثر تحقيق أمور هذا الطريق قائلا: «متى انحدر ليسياس الأمير أفحص عن أموركم».","24:23":"وأمر قائد المئة أن يحرس بولس وتكون له رخصة وأن لا يمنع أحدا من أصحابه أن يخدمه أو يأتي إليه.","24:24":"ثم بعد أيام جاء فيلكس مع دروسلا امرأته وهي يهودية. فاستحضر بولس وسمع منه عن الإيمان بالمسيح.","24:25":"وبينما كان يتكلم عن البر والتعفف والدينونة العتيدة أن تكون ارتعب فيلكس وأجاب: «أما الآن فاذهب ومتى حصلت على وقت أستدعيك».","24:26":"وكان أيضا يرجو أن يعطيه بولس دراهم ليطلقه ولذلك كان يستحضره مرارا أكثر ويتكلم معه.","24:27":"ولكن لما كملت سنتان قبل فيلكس بوركيوس فستوس خليفة له. وإذ كان فيلكس يريد أن يودع اليهود منة ترك بولس مقيدا.","25:1":"فلما قدم فستوس إلى الولاية صعد بعد ثلاثة أيام من قيصرية إلى أورشليم.","25:2":"فعرض له رئيس الكهنة ووجوه اليهود ضد بولس والتمسوا منه","25:3":"طالبين عليه منة أن يستحضره إلى أورشليم وهم صانعون كمينا ليقتلوه في الطريق.","25:4":"فأجاب فستوس أن يحرس بولس في قيصرية وأنه هو مزمع أن ينطلق عاجلا.","25:5":"وقال: «فلينزل معي الذين هم بينكم مقتدرون. وإن كان في هذا الرجل شيء فليشتكوا عليه».","25:6":"وبعد ما صرف عندهم أكثر من عشرة أيام انحدر إلى قيصرية. وفي الغد جلس على كرسي الولاية وأمر أن يؤتى ببولس.","25:7":"فلما حضر وقف حوله اليهود الذين كانوا قد انحدروا من أورشليم وقدموا على بولس دعاوي كثيرة وثقيلة لم يقدروا أن يبرهنوها.","25:8":"إذ كان هو يحتج: «أني ما أخطأت بشيء لا إلى ناموس اليهود ولا إلى الهيكل ولا إلى قيصر».","25:9":"ولكن فستوس إذ كان يريد أن يودع اليهود منة قال لبولس: «أتشاء أن تصعد إلى أورشليم لتحاكم هناك لدي من جهة هذه الأمور؟»","25:10":"فقال بولس: «أنا واقف لدى كرسي ولاية قيصر حيث ينبغي أن أحاكم. أنا لم أظلم اليهود بشيء كما تعلم أنت أيضا جيدا.","25:11":"لأني إن كنت آثما أو صنعت شيئا يستحق الموت فلست أستعفي من الموت. ولكن إن لم يكن شيء مما يشتكي علي به هؤلاء فليس أحد يستطيع أن يسلمني لهم. إلى قيصر أنا رافع دعواي».","25:12":"حينئذ تكلم فستوس مع أرباب المشورة فأجاب: «إلى قيصر رفعت دعواك. إلى قيصر تذهب».","25:13":"وبعدما مضت أيام أقبل أغريباس الملك وبرنيكي إلى قيصرية ليسلما على فستوس.","25:14":"ولما كانا يصرفان هناك أياما كثيرة عرض فستوس على الملك أمر بولس قائلا: «يوجد رجل تركه فيلكس أسيرا","25:15":"وعرض لي عنه رؤساء الكهنة ومشايخ اليهود لما كنت في أورشليم طالبين حكما عليه.","25:16":"فأجبتهم أن ليس للرومان عادة أن يسلموا أحدا للموت قبل أن يكون المشكو عليه مواجهة مع المشتكين فيحصل على فرصة للاحتجاج عن الشكوى.","25:17":"فلما اجتمعوا إلى هنا جلست من دون إمهال في الغد على كرسي الولاية وأمرت أن يؤتى بالرجل.","25:18":"فلما وقف المشتكون حوله لم يأتوا بعلة واحدة مما كنت أظن.","25:19":"لكن كان لهم عليه مسائل من جهة ديانتهم وعن واحد اسمه يسوع قد مات وكان بولس يقول إنه حي.","25:20":"وإذ كنت مرتابا في المسألة عن هذا قلت: ألعله يشاء أن يذهب إلى أورشليم ويحاكم هناك من جهة هذه الأمور؟","25:21":"ولكن لما رفع بولس دعواه لكي يحفظ لفحص أوغسطس أمرت بحفظه إلى أن أرسله إلى قيصر».","25:22":"فقال أغريباس لفستوس: «كنت أريد أنا أيضا أن أسمع الرجل». فقال: «غدا تسمعه».","25:23":"ففي الغد لما جاء أغريباس وبرنيكي في احتفال عظيم ودخلا إلى دار الاستماع مع الأمراء ورجال المدينة المقدمين أمر فستوس فأتي ببولس.","25:24":"فقال فستوس: «أيها الملك أغريباس والرجال الحاضرون معنا أجمعون أنتم تنظرون هذا الذي توسل إلي من جهته كل جمهور اليهود في أورشليم وهنا صارخين أنه لا ينبغي أن يعيش بعد.","25:25":"وأما أنا فلما وجدت أنه لم يفعل شيئا يستحق الموت وهو قد رفع دعواه إلى أوغسطس عزمت أن أرسله.","25:26":"وليس لي شيء يقين من جهته لأكتب إلى السيد. لذلك أتيت به لديكم ولا سيما لديك أيها الملك أغريباس حتى إذا صار الفحص يكون لي شيء لأكتب.","25:27":"لأني أرى حماقة أن أرسل أسيرا ولا أشير إلى الدعاوي التي عليه».","26:1":"فقال أغريباس لبولس: «مأذون لك أن تتكلم لأجل نفسك». حينئذ بسط بولس يده وجعل يحتج:","26:2":"«إني أحسب نفسي سعيدا أيها الملك أغريباس إذ أنا مزمع أن أحتج اليوم لديك عن كل ما يحاكمني به اليهود.","26:3":"لا سيما وأنت عالم بجميع العوائد والمسائل التي بين اليهود. لذلك ألتمس منك أن تسمعني بطول الأناة.","26:4":"فسيرتي منذ حداثتي التي من البداءة كانت بين أمتي في أورشليم يعرفها جميع اليهود","26:5":"عالمين بي من الأول - إن أرادوا أن يشهدوا - أني حسب مذهب عبادتنا الأضيق عشت فريسيا.","26:6":"والآن أنا واقف أحاكم على رجاء الوعد الذي صار من الله لآبائنا","26:7":"الذي أسباطنا الاثنا عشر يرجون نواله عابدين بالجهد ليلا ونهارا. فمن أجل هذا الرجاء أنا أحاكم من اليهود أيها الملك أغريباس.","26:8":"لماذا يعد عندكم أمرا لا يصدق إن أقام الله أمواتا؟","26:9":"فأنا ارتأيت في نفسي أنه ينبغي أن أصنع أمورا كثيرة مضادة لاسم يسوع الناصري.","26:10":"وفعلت ذلك أيضا في أورشليم فحبست في سجون كثيرين من القديسين آخذا السلطان من قبل رؤساء الكهنة. ولما كانوا يقتلون ألقيت قرعة بذلك.","26:11":"وفي كل المجامع كنت أعاقبهم مرارا كثيرة وأضطرهم إلى التجديف. وإذ أفرط حنقي عليهم كنت أطردهم إلى المدن التي في الخارج.","26:12":"«ولما كنت ذاهبا في ذلك إلى دمشق بسلطان ووصية من رؤساء الكهنة","26:13":"رأيت في نصف النهار في الطريق أيها الملك نورا من السماء أفضل من لمعان الشمس قد أبرق حولي وحول الذاهبين معي.","26:14":"فلما سقطنا جميعنا على الأرض سمعت صوتا يكلمني باللغة العبرانية: شاول شاول لماذا تضطهدني؟ صعب عليك أن ترفس مناخس","26:15":"فقلت أنا: من أنت يا سيد؟ فقال: أنا يسوع الذي أنت تضطهده.","26:16":"ولكن قم وقف على رجليك لأني لهذا ظهرت لك لأنتخبك خادما وشاهدا بما رأيت وبما سأظهر لك به","26:17":"منقذا إياك من الشعب ومن الأمم الذين أنا الآن أرسلك إليهم","26:18":"لتفتح عيونهم كي يرجعوا من ظلمات إلى نور ومن سلطان الشيطان إلى الله حتى ينالوا بالإيمان بي غفران الخطايا ونصيبا مع المقدسين.","26:19":"«من ثم أيها الملك أغريباس لم أكن معاندا للرؤيا السماوية","26:20":"بل أخبرت أولا الذين في دمشق وفي أورشليم حتى جميع كورة اليهودية ثم الأمم أن يتوبوا ويرجعوا إلى الله عاملين أعمالا تليق بالتوبة.","26:21":"من أجل ذلك أمسكني اليهود في الهيكل وشرعوا في قتلي.","26:22":"فإذ حصلت على معونة من الله بقيت إلى هذا اليوم شاهدا للصغير والكبير. وأنا لا أقول شيئا غير ما تكلم الأنبياء وموسى أنه عتيد أن يكون:","26:23":"إن يؤلم المسيح يكن هو أول قيامة الأموات مزمعا أن ينادي بنور للشعب وللأمم».","26:24":"وبينما هو يحتج بهذا قال فستوس بصوت عظيم: «أنت تهذي يا بولس! الكتب الكثيرة تحولك إلى الهذيان».","26:25":"فقال: «لست أهذي أيها العزيز فستوس بل أنطق بكلمات الصدق والصحو.","26:26":"لأنه من جهة هذه الأمور عالم الملك الذي أكلمه جهارا إذ أنا لست أصدق أن يخفى عليه شيء من ذلك لأن هذا لم يفعل في زاوية.","26:27":"أتؤمن أيها الملك أغريباس بالأنبياء؟ أنا أعلم أنك تؤمن».","26:28":"فقال أغريباس لبولس: «بقليل تقنعني أن أصير مسيحيا».","26:29":"فقال بولس: «كنت أصلي إلى الله أنه بقليل وبكثير ليس أنت فقط بل أيضا جميع الذين يسمعونني اليوم يصيرون هكذا كما أنا ما خلا هذه القيود».","26:30":"فلما قال هذا قام الملك والوالي وبرنيكي والجالسون معهم","26:31":"وانصرفوا وهم يكلمون بعضهم بعضا قائلين: «إن هذا الإنسان ليس يفعل شيئا يستحق الموت أو القيود».","26:32":"وقال أغريباس لفستوس: «كان يمكن أن يطلق هذا الإنسان لو لم يكن قد رفع دعواه إلى قيصر».","27:1":"فلما استقر الرأي أن نسافر في البحر إلى إيطاليا سلموا بولس وأسرى آخرين إلى قائد مئة من كتيبة أوغسطس اسمه يوليوس.","27:2":"فصعدنا إلى سفينة أدراميتينية وأقلعنا مزمعين أن نسافر مارين بالمواضع التي في أسيا. وكان معنا أرسترخس رجل مكدوني من تسالونيكي.","27:3":"وفي اليوم الآخر أقبلنا إلى صيداء فعامل يوليوس بولس بالرفق وأذن أن يذهب إلى أصدقائه ليحصل على عناية منهم.","27:4":"ثم أقلعنا من هناك وسافرنا في البحر من تحت قبرس لأن الرياح كانت مضادة.","27:5":"وبعد ما عبرنا البحر الذي بجانب كيليكية وبمفيلية نزلنا إلى ميرا ليكية.","27:6":"فإذ وجد قائد المئة هناك سفينة إسكندرية مسافرة إلى إيطاليا أدخلنا فيها.","27:7":"ولما كنا نسافر رويدا أياما كثيرة وبالجهد صرنا بقرب كنيدس ولم تمكنا الريح أكثر سافرنا من تحت كريت بقرب سلموني.","27:8":"ولما تجاوزناها بالجهد جئنا إلى مكان يقال له «المواني الحسنة» التي بقربها مدينة لسائية.","27:9":"ولما مضى زمان طويل وصار السفر في البحر خطرا إذ كان الصوم أيضا قد مضى جعل بولس ينذرهم","27:10":"قائلا: «أيها الرجال أنا أرى أن هذا السفر عتيد أن يكون بضرر وخسارة كثيرة ليس للشحن والسفينة فقط بل لأنفسنا أيضا».","27:11":"ولكن كان قائد المئة ينقاد إلى ربان السفينة وإلى صاحبها أكثر مما إلى قول بولس.","27:12":"ولأن موقع المينا لم يكن صالحا للمشتى استقر رأي أكثرهم أن يقلعوا من هناك أيضا عسى أن يمكنهم الإقبال إلى فينكس ليشتوا فيها. وهي مينا في كريت تنظر نحو الجنوب والشمال الغربيين.","27:13":"فلما نسمت ريح جنوب ظنوا أنهم قد ملكوا مقصدهم فرفعوا المرساة وطفقوا يتجاوزون كريت على أكثر قرب.","27:14":"ولكن بعد قليل هاجت عليها ريح زوبعية يقال لها «أوروكليدون».","27:15":"فلما خطفت السفينة ولم يمكنها أن تقابل الريح سلمنا فصرنا نحمل.","27:16":"فجرينا تحت جزيرة يقال لها «كلودي» وبالجهد قدرنا أن نملك القارب.","27:17":"ولما رفعوه طفقوا يستعملون معونات حازمين السفينة وإذ كانوا خائفين أن يقعوا في السيرتس أنزلوا القلوع وهكذا كانوا يحملون.","27:18":"وإذ كنا في نوء عنيف جعلوا يفرغون في الغد.","27:19":"وفي اليوم الثالث رمينا بأيدينا أثاث السفينة.","27:20":"وإذ لم تكن الشمس ولا النجوم تظهر أياما كثيرة واشتد علينا نوء ليس بقليل انتزع أخيرا كل رجاء في نجاتنا.","27:21":"فلما حصل صوم كثير حينئذ وقف بولس في وسطهم وقال: «كان ينبغي أيها الرجال أن تذعنوا لي ولا تقلعوا من كريت فتسلموا من هذا الضرر والخسارة.","27:22":"والآن أنذركم أن تسروا لأنه لا تكون خسارة نفس واحدة منكم إلا السفينة.","27:23":"لأنه وقف بي هذه الليلة ملاك الإله الذي أنا له والذي أعبده","27:24":"قائلا: لا تخف يا بولس. ينبغي لك أن تقف أمام قيصر. وهوذا قد وهبك الله جميع المسافرين معك.","27:25":"لذلك سروا أيها الرجال لأني أومن بالله أنه يكون هكذا كما قيل لي.","27:26":"ولكن لا بد أن نقع على جزيرة».","27:27":"فلما كانت الليلة الرابعة عشرة ونحن نحمل تائهين في بحر أدريا ظن النوتية نحو نصف الليل أنهم اقتربوا إلى بر.","27:28":"فقاسوا ووجدوا عشرين قامة. ولما مضوا قليلا قاسوا أيضا فوجدوا خمس عشرة قامة.","27:29":"وإذ كانوا يخافون أن يقعوا على مواضع صعبة رموا من المؤخر أربع مراس وكانوا يطلبون أن يصير النهار.","27:30":"ولما كان النوتية يطلبون أن يهربوا من السفينة وأنزلوا القارب إلى البحر بعلة أنهم مزمعون أن يمدوا مراسي من المقدم","27:31":"قال بولس لقائد المئة والعسكر: «إن لم يبق هؤلاء في السفينة فأنتم لا تقدرون أن تنجوا».","27:32":"حينئذ قطع العسكر حبال القارب وتركوه يسقط.","27:33":"وحتى قارب أن يصير النهار كان بولس يطلب إلى الجميع أن يتناولوا طعاما قائلا: «هذا هو اليوم الرابع عشر وأنتم منتظرون لا تزالون صائمين ولم تأخذوا شيئا.","27:34":"لذلك ألتمس منكم أن تتناولوا طعاما لأن هذا يكون مفيدا لنجاتكم لأنه لا تسقط شعرة من رأس واحد منكم».","27:35":"ولما قال هذا أخذ خبزا وشكر الله أمام الجميع وكسر وابتدأ يأكل.","27:36":"فصار الجميع مسرورين وأخذوا هم أيضا طعاما.","27:37":"وكنا في السفينة جميع الأنفس مئتين وستة وسبعين.","27:38":"ولما شبعوا من الطعام طفقوا يخففون السفينة طارحين الحنطة في البحر.","27:39":"ولما صار النهار لم يكونوا يعرفون الأرض ولكنهم أبصروا خليجا له شاطئ فأجمعوا أن يدفعوا إليه السفينة إن أمكنهم.","27:40":"فلما نزعوا المراسي تاركين إياها في البحر وحلوا ربط الدفة أيضا رفعوا قلعا للريح الهابة وأقبلوا إلى الشاطئ.","27:41":"وإذ وقعوا على موضع بين بحرين شططوا السفينة فارتكز المقدم ولبث لا يتحرك. وأما المؤخر فكان ينحل من عنف الأمواج.","27:42":"فكان رأي العسكر أن يقتلوا الأسرى لئلا يسبح أحد منهم فيهرب.","27:43":"ولكن قائد المئة إذ كان يريد أن يخلص بولس منعهم من هذا الرأي وأمر أن القادرين على السباحة يرمون أنفسهم أولا فيخرجون إلى البر","27:44":"والباقين بعضهم على ألواح وبعضهم على قطع من السفينة. فهكذا حدث أن الجميع نجوا إلى البر.","28:1":"ولما نجوا وجدوا أن الجزيرة تدعى مليطة.","28:2":"فقدم أهلها البرابرة لنا إحسانا غير المعتاد لأنهم أوقدوا نارا وقبلوا جميعنا من أجل المطر الذي أصابنا ومن أجل البرد.","28:3":"فجمع بولس كثيرا من القضبان ووضعها على النار فخرجت من الحرارة أفعى ونشبت في يده.","28:4":"فلما رأى البرابرة الوحش معلقا بيده قال بعضهم لبعض: «لا بد أن هذا الإنسان قاتل لم يدعه العدل يحيا ولو نجا من البحر».","28:5":"فنفض هو الوحش إلى النار ولم يتضرر بشيء رديء.","28:6":"وأما هم فكانوا ينتظرون أنه عتيد أن ينتفخ أو يسقط بغتة ميتا. فإذ انتظروا كثيرا ورأوا أنه لم يعرض له شيء مضر تغيروا وقالوا: «هو إله!».","28:7":"وكان في ما حول ذلك الموضع ضياع لمقدم الجزيرة الذي اسمه بوبليوس. فهذا قبلنا وأضافنا بملاطفة ثلاثة أيام.","28:8":"فحدث أن أبا بوبليوس كان مضطجعا معترى بحمى وسحج. فدخل إليه بولس وصلى ووضع يديه عليه فشفاه.","28:9":"فلما صار هذا كان الباقون الذين بهم أمراض في الجزيرة يأتون ويشفون.","28:10":"فأكرمنا هؤلاء إكرامات كثيرة. ولما أقلعنا زودونا بما يحتاج إليه.","28:11":"وبعد ثلاثة أشهر أقلعنا في سفينة إسكندرية موسومة بعلامة الجوزاء كانت قد شتت في الجزيرة.","28:12":"فنزلنا إلى سيراكوس ومكثنا ثلاثة أيام.","28:13":"ثم من هناك درنا وأقبلنا إلى ريغيون. وبعد يوم واحد حدثت ريح جنوب فجئنا في اليوم الثاني إلى بوطيولي","28:14":"حيث وجدنا إخوة فطلبوا إلينا أن نمكث عندهم سبعة أيام. وهكذا أتينا إلى رومية.","28:15":"ومن هناك لما سمع الإخوة بخبرنا خرجوا لاستقبالنا إلى فورن أبيوس والثلاثة الحوانيت. فلما رآهم بولس شكر الله وتشجع.","28:16":"ولما أتينا إلى رومية سلم قائد المئة الأسرى إلى رئيس المعسكر وأما بولس فأذن له أن يقيم وحده مع العسكري الذي كان يحرسه.","28:17":"وبعد ثلاثة أيام استدعى بولس الذين كانوا وجوه اليهود. فلما اجتمعوا قال لهم: «أيها الرجال الإخوة مع أني لم أفعل شيئا ضد الشعب أو عوائد الآباء أسلمت مقيدا من أورشليم إلى أيدي الرومان","28:18":"الذين لما فحصوا كانوا يريدون أن يطلقوني لأنه لم تكن في علة واحدة للموت.","28:19":"ولكن لما قاوم اليهود اضطررت أن أرفع دعواي إلى قيصر - ليس كأن لي شيئا لأشتكي به على أمتي.","28:20":"فلهذا السبب طلبتكم لأراكم وأكلمكم لأني من أجل رجاء إسرائيل موثق بهذه السلسلة».","28:21":"فقالوا له: «نحن لم نقبل كتابات فيك من اليهودية ولا أحد من الإخوة جاء فأخبرنا أو تكلم عنك بشيء ردي.","28:22":"ولكننا نستحسن أن نسمع منك ماذا ترى لأنه معلوم عندنا من جهة هذا المذهب أنه يقاوم في كل مكان».","28:23":"فعينوا له يوما فجاء إليه كثيرون إلى المنزل فطفق يشرح لهم شاهدا بملكوت الله ومقنعا إياهم من ناموس موسى والأنبياء بأمر يسوع من الصباح إلى المساء.","28:24":"فاقتنع بعضهم بما قيل وبعضهم لم يؤمنوا.","28:25":"فانصرفوا وهم غير متفقين بعضهم مع بعض لما قال بولس كلمة واحدة: «إنه حسنا كلم الروح القدس آباءنا بإشعياء النبي","28:26":"قائلا: اذهب إلى هذا الشعب وقل: ستسمعون سمعا ولا تفهمون وستنظرون نظرا ولا تبصرون.","28:27":"لأن قلب هذا الشعب قد غلظ وبآذانهم سمعوا ثقيلا وأعينهم أغمضوها. لئلا يبصروا بأعينهم ويسمعوا بآذانهم ويفهموا بقلوبهم ويرجعوا فأشفيهم.","28:28":"فليكن معلوما عندكم أن خلاص الله قد أرسل إلى الأمم وهم سيسمعون».","28:29":"ولما قال هذا مضى اليهود ولهم مباحثة كثيرة فيما بينهم.","28:30":"وأقام بولس سنتين كاملتين في بيت استأجره لنفسه. وكان يقبل جميع الذين يدخلون إليه","28:31":"كارزا بملكوت الله ومعلما بأمر الرب يسوع المسيح بكل مجاهرة بلا مانع."};
